from __future__ import annotations

import logging

import httpx

from diligence.settings import Settings, get_settings

log = logging.getLogger(__name__)


class LLMClient:
    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings or get_settings()

    def _headers(self) -> dict[str, str]:
        return {
            "Authorization": f"Bearer {self.settings.llm_api_key}",
            "Content-Type": "application/json",
        }

    def ping(self) -> dict:
        url = f"{self.settings.llm_base_url.rstrip('/')}/models"
        with httpx.Client(timeout=10) as client:
            response = client.get(url, headers=self._headers())
            response.raise_for_status()
            return response.json()

    def chat(self, messages: list[dict[str, str]], temperature: float = 0.2, max_tokens: int = 700) -> str:
        url = f"{self.settings.llm_base_url.rstrip('/')}/chat/completions"
        payload = {
            "model": self.settings.llm_model,
            "messages": messages,
            "temperature": temperature,
            "max_tokens": max_tokens,
        }
        try:
            with httpx.Client(timeout=90) as client:
                response = client.post(url, headers=self._headers(), json=payload)
                response.raise_for_status()
                data = response.json()
            return data["choices"][0]["message"]["content"].strip()
        except Exception as exc:
            log.warning("LLM chat failed: %s", exc)
            return ""

    def embed(self, texts: list[str]) -> list[list[float]]:
        host = self.settings.ollama_host
        vectors: list[list[float]] = []
        with httpx.Client(timeout=60) as client:
            for text in texts:
                response = client.post(
                    f"{host}/api/embeddings",
                    json={"model": self.settings.embedding_model, "prompt": text},
                )
                if response.status_code == 404:
                    response = client.post(
                        f"{host}/api/embed",
                        json={"model": self.settings.embedding_model, "input": text},
                    )
                response.raise_for_status()
                data = response.json()
                if "embedding" in data:
                    vectors.append(data["embedding"])
                elif "embeddings" in data:
                    vectors.append(data["embeddings"][0])
                else:
                    raise RuntimeError(f"Unexpected embed payload: {data.keys()}")
        return vectors

{
  "name": "night-desk",
  "private": true,
  "scripts": {
    "dev": "pnpm --dir apps/web dev --hostname 127.0.0.1 --port 3000",
    "sample": "pnpm --dir apps/web exec tsx lib/diligence/cli.ts sample",
    "run": "pnpm --dir apps/web exec tsx lib/diligence/cli.ts run",
    "build": "pnpm --dir apps/web build"
  }
}

export type Severity = "contradiction" | "unsupported" | "missing";
export type FlagType = "highlight" | "note" | "area";
export type DocKind = "deck" | "financials" | "cap_table" | "metrics" | "other";
export type DealStatus =
  | "received"
  | "ingesting"
  | "graphing"
  | "diligence"
  | "annotating"
  | "ready"
  | "error";

export type Citation = {
  filename: string;
  page?: number;
  sheet?: string;
  label?: string;
};

export type IngestedDoc = {
  docId: string;
  filename: string;
  kind: DocKind;
  path: string;
  markdown: string;
  pageTexts: Record<number, string>;
};

export type Metric = {
  name: string;
  value: number;
  unit: "usd" | "months" | "people" | "pct";
  raw: string;
  sourceKind: DocKind;
  citation: Citation;
};

export type Flag = {
  id: string;
  docId: string;
  page: number | null;
  type: FlagType;
  severity: Severity;
  comment: string;
  sourceCitation: string;
  quote: string;
  metric?: string;
};

export type GraphNode = {
  id: string;
  type: string;
  label: string;
  value?: string;
  source?: string;
  severity?: Severity;
};

export type GraphEdge = {
  source: string;
  target: string;
  rel: string;
  severity?: Severity;
};

export type KnowledgeGraph = {
  nodes: GraphNode[];
  edges: GraphEdge[];
};

export type Memo = {
  title: string;
  company: string;
  riskScore: number;
  verdict: string;
  summary: string;
  flaggedItems: string[];
  openQuestions: string[];
  bodyMarkdown: string;
};

export type DealEvent = {
  at: string;
  stage: string;
  message: string;
};

export type Deal = {
  id: string;
  name: string;
  company: string;
  status: DealStatus;
  createdAt: string;
  updatedAt: string;
  sourcePath: string;
  error?: string;
  docs: IngestedDoc[];
  metrics: Metric[];
  flags: Flag[];
  graph: KnowledgeGraph;
  memo?: Memo;
  riskScore?: number;
  events: DealEvent[];
  deckFilename?: string;
};

export type DealSummary = {
  id: string;
  name: string;
  company: string;
  status: DealStatus;
  createdAt: string;
  updatedAt: string;
  riskScore?: number;
  flagCounts: Record<Severity, number>;
  docCount: number;
  error?: string;
  deckFilename?: string;
};

import { existsSync, mkdirSync } from "node:fs";
import path from "node:path";

export function repoRoot(): string {
  if (process.env.ROOT_DIR) return path.resolve(process.env.ROOT_DIR);
  let dir = process.cwd();
  for (let i = 0; i < 8; i++) {
    if (
      existsSync(path.join(dir, ".env.example")) ||
      existsSync(path.join(dir, "sample"))
    ) {
      return dir;
    }
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return path.resolve(process.cwd(), "../..");
}

export function dirs() {
  const root = repoRoot();
  const paths = {
    root,
    inbox: path.join(root, "inbox"),
    outbox: path.join(root, "outbox"),
    data: path.join(root, "data", "deals"),
    sample: path.join(root, "sample", "northstar"),
  };
  for (const dir of [paths.inbox, paths.outbox, paths.data, paths.sample]) {
    mkdirSync(dir, { recursive: true });
  }
  return paths;
}

export function settings() {
  return {
    llmBaseUrl: process.env.LLM_BASE_URL ?? "http://127.0.0.1:11434/v1",
    llmApiKey: process.env.LLM_API_KEY ?? "ollama",
    llmModel: process.env.LLM_MODEL ?? "gemma3:latest",
    embeddingModel: process.env.EMBEDDING_MODEL ?? "nomic-embed-text",
  };
}

export function citationLabel(c: {
  filename: string;
  page?: number;
  sheet?: string;
  label?: string;
}): string {
  return [c.filename, c.sheet, c.page ? `slide ${c.page}` : "", c.label]
    .filter(Boolean)
    .join(" · ");
}

import { settings } from "./paths";

function headers() {
  const { llmApiKey } = settings();
  return {
    Authorization: `Bearer ${llmApiKey}`,
    "Content-Type": "application/json",
  };
}

function ollamaHost() {
  return settings().llmBaseUrl.replace(/\/v1\/?$/, "");
}

export async function pingModel(): Promise<{ ok: boolean; models: string[] }> {
  try {
    const res = await fetch(`${settings().llmBaseUrl.replace(/\/$/, "")}/models`, {
      headers: headers(),
    });
    if (!res.ok) return { ok: false, models: [] };
    const data = (await res.json()) as { data?: { id: string }[] };
    return { ok: true, models: (data.data ?? []).map((m) => m.id) };
  } catch {
    return { ok: false, models: [] };
  }
}

export async function chat(
  messages: { role: "system" | "user" | "assistant"; content: string }[],
  opts?: { maxTokens?: number },
): Promise<string> {
  try {
    const res = await fetch(`${settings().llmBaseUrl.replace(/\/$/, "")}/chat/completions`, {
      method: "POST",
      headers: headers(),
      body: JSON.stringify({
        model: settings().llmModel,
        messages,
        temperature: 0.2,
        max_tokens: opts?.maxTokens ?? 500,
      }),
    });
    if (!res.ok) return "";
    const data = (await res.json()) as {
      choices?: { message?: { content?: string } }[];
    };
    return data.choices?.[0]?.message?.content?.trim() ?? "";
  } catch {
    return "";
  }
}

export async function embed(texts: string[]): Promise<number[][]> {
  const vectors: number[][] = [];
  const host = ollamaHost();
  const model = settings().embeddingModel;
  for (const text of texts) {
    const openai = await fetch(`${settings().llmBaseUrl.replace(/\/$/, "")}/embeddings`, {
      method: "POST",
      headers: headers(),
      body: JSON.stringify({ model, input: text }),
    });
    if (openai.ok) {
      const data = (await openai.json()) as { data?: { embedding: number[] }[] };
      if (data.data?.[0]?.embedding) {
        vectors.push(data.data[0].embedding);
        continue;
      }
    }
    const native = await fetch(`${host}/api/embeddings`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model, prompt: text }),
    });
    if (!native.ok) throw new Error(`embed failed: ${native.status}`);
    const data = (await native.json()) as {
      embedding?: number[];
      embeddings?: number[][];
    };
    const vec = data.embedding ?? data.embeddings?.[0];
    if (!vec) throw new Error("embed payload missing vector");
    vectors.push(vec);
  }
  return vectors;
}

export function cosine(a: number[], b: number[]): number {
  let dot = 0;
  let na = 0;
  let nb = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  if (!na || !nb) return 0;
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

import { createHash } from "node:crypto";
import { readdir, readFile, stat } from "node:fs/promises";
import path from "node:path";
import { toMarkdown } from "@firecrawl/anydoc";
import type { DocKind, IngestedDoc } from "./types";

const OFFICE = new Set([".pdf", ".pptx", ".ppt", ".xlsx", ".xls", ".docx", ".doc", ".csv"]);

function kindFromName(filename: string): DocKind {
  const n = filename.toLowerCase();
  if (/(deck|pitch|slides)/.test(n)) return "deck";
  if (/(cap[-_ ]?table|captable|ownership)/.test(n)) return "cap_table";
  if (/(financial|model|pnl|p&l|burn)/.test(n)) return "financials";
  if (/(metric|kpi|cohort)/.test(n)) return "metrics";
  if (n.endsWith(".pdf") || n.endsWith(".pptx")) return "deck";
  if (n.endsWith(".xlsx") || n.endsWith(".xls")) return "financials";
  return "other";
}

async function walkFiles(dir: string): Promise<string[]> {
  const out: string[] = [];
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.name.startsWith(".")) continue;
    if (entry.isDirectory()) out.push(...(await walkFiles(full)));
    else if (OFFICE.has(path.extname(entry.name).toLowerCase())) out.push(full);
  }
  return out;
}

async function pdfPageTexts(filePath: string): Promise<Record<number, string>> {
  if (path.extname(filePath).toLowerCase() !== ".pdf") return {};
  try {
    const { getDocument } = await import("pdfjs-dist/legacy/build/pdf.mjs");
    const data = new Uint8Array(await readFile(filePath));
    const doc = await getDocument({ data, useSystemFonts: true }).promise;
    const pages: Record<number, string> = {};
    for (let i = 1; i <= doc.numPages; i++) {
      const page = await doc.getPage(i);
      const content = await page.getTextContent();
      pages[i] = content.items
        .map((item) => ("str" in item ? item.str : ""))
        .join(" ")
        .replace(/\s+/g, " ")
        .trim();
    }
    return pages;
  } catch {
    return {};
  }
}

function tagPages(filename: string, pageTexts: Record<number, string>, markdown: string): string {
  const tagged = Object.entries(pageTexts)
    .sort(([a], [b]) => Number(a) - Number(b))
    .map(([page, text]) => `<!-- source:${filename} page:${page} -->\n## Slide ${page}\n\n${text}`)
    .join("\n\n");
  if (tagged) return `${tagged}\n\n---\n\n${markdown}`;
  return `<!-- source:${filename} -->\n${markdown}`;
}

export async function ingestFolder(folder: string): Promise<IngestedDoc[]> {
  const files = await walkFiles(folder);
  const docs: IngestedDoc[] = [];
  for (const filePath of files) {
    const filename = path.basename(filePath);
    const info = await stat(filePath);
    if (!info.isFile()) continue;
    let markdown = "";
    try {
      markdown = await toMarkdown(filePath);
    } catch (error) {
      const code = (error as { code?: string }).code;
      if (code === "needsOcr") {
        markdown = `<!-- unreadable scanned pages in ${filename} -->`;
      } else {
        markdown = `<!-- parse error ${filename}: ${(error as Error).message} -->`;
      }
    }
    const pageTexts = await pdfPageTexts(filePath);
    const docId = createHash("sha1").update(filePath).digest("hex").slice(0, 12);
    docs.push({
      docId,
      filename,
      kind: kindFromName(filename),
      path: filePath,
      markdown: tagPages(filename, pageTexts, markdown),
      pageTexts,
    });
  }
  return docs;
}

import ExcelJS from "exceljs";
import { citationLabel } from "./paths";
import type { Citation, DocKind, IngestedDoc, Metric } from "./types";

const MONEY = { k: 1_000, m: 1_000_000, b: 1_000_000_000 };

function money(num: string, suffix?: string): number {
  const n = Number(num.replace(/,/g, ""));
  if (!Number.isFinite(n)) return NaN;
  const mul = suffix ? MONEY[suffix.toLowerCase() as keyof typeof MONEY] ?? 1 : 1;
  return n * mul;
}

type Spec = {
  name: string;
  unit: Metric["unit"];
  patterns: RegExp[];
};

const SPECS: Spec[] = [
  {
    name: "arr",
    unit: "usd",
    patterns: [
      /(?:ARR|annual recurring revenue)[^\n$]{0,48}\$([0-9][0-9.,]*)\s*([MmBbKk])?/i,
      /\$([0-9][0-9.,]*)\s*([MmBbKk])?\s*(?:in\s+)?ARR/i,
    ],
  },
  {
    name: "runway_months",
    unit: "months",
    patterns: [
      /([0-9]+(?:\.[0-9]+)?)\s*[-–]?\s*months?\s+(?:of\s+)?runway/i,
      /runway[:\s]+([0-9]+(?:\.[0-9]+)?)\s*months?/i,
    ],
  },
  {
    name: "headcount",
    unit: "people",
    patterns: [
      /(?:team of|headcount[:\s]+|employees[:\s]+)([0-9]{1,4})/i,
      /([0-9]{1,4})\s+(?:people|employees|FTEs?)\b/i,
    ],
  },
  {
    name: "founder_ownership_pct",
    unit: "pct",
    patterns: [
      /founders?(?:\s+retain|\s+own|\s+ownership)?[^\n%]{0,40}([0-9]+(?:\.[0-9]+)?)\s*%/i,
      /founder(?:s)?[^\n]{0,20}([0-9]+(?:\.[0-9]+)?)\s*%\s*(?:FD|fully diluted)?/i,
    ],
  },
  {
    name: "burn_monthly",
    unit: "usd",
    patterns: [
      /(?:monthly (?:net )?burn|net burn)[^\n$]{0,40}\$?([0-9][0-9.,]*)\s*([MmKk])?/i,
    ],
  },
  {
    name: "cash",
    unit: "usd",
    patterns: [
      /(?:cash(?: on hand)?|cash balance)[^\n$]{0,40}\$?([0-9][0-9.,]*)\s*([MmKk])?/i,
    ],
  },
  {
    name: "tam",
    unit: "usd",
    patterns: [/(?:TAM|total addressable market)[^\n$]{0,40}\$([0-9][0-9.,]*)\s*([BbMm])/i],
  },
  {
    name: "nrr",
    unit: "pct",
    patterns: [/(?:NRR|net revenue retention)[^\n%]{0,24}([0-9]+(?:\.[0-9]+)?)\s*%/i],
  },
  {
    name: "raise",
    unit: "usd",
    patterns: [/(?:raising|the ask|series [a-z] of)[^\n$]{0,24}\$([0-9][0-9.,]*)\s*([Mm])/i],
  },
];

const SHEET_KEYS: Record<string, { name: string; unit: Metric["unit"] }> = {
  arr: { name: "arr", unit: "usd" },
  "annual recurring revenue": { name: "arr", unit: "usd" },
  "monthly burn": { name: "burn_monthly", unit: "usd" },
  "net burn": { name: "burn_monthly", unit: "usd" },
  "runway months": { name: "runway_months", unit: "months" },
  runway: { name: "runway_months", unit: "months" },
  headcount: { name: "headcount", unit: "people" },
  employees: { name: "headcount", unit: "people" },
  "cash on hand": { name: "cash", unit: "usd" },
  cash: { name: "cash", unit: "usd" },
  "founder ownership fd": { name: "founder_ownership_pct", unit: "pct" },
  "founders fd %": { name: "founder_ownership_pct", unit: "pct" },
  nrr: { name: "nrr", unit: "pct" },
};

function pageForQuote(doc: IngestedDoc, quote: string): number | undefined {
  const needle = quote.toLowerCase();
  for (const [page, text] of Object.entries(doc.pageTexts)) {
    if (text.toLowerCase().includes(needle)) return Number(page);
  }
  const mark = doc.markdown.match(
    new RegExp(`page:(\\d+)[\\s\\S]{0,400}${quote.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`, "i"),
  );
  return mark ? Number(mark[1]) : undefined;
}

function fromMarkdown(doc: IngestedDoc): Metric[] {
  const found: Metric[] = [];
  for (const spec of SPECS) {
    for (const re of spec.patterns) {
      const match = re.exec(doc.markdown);
      if (!match) continue;
      let value: number;
      if (spec.unit === "usd") value = money(match[1], match[2]);
      else value = Number(match[1]);
      if (!Number.isFinite(value)) continue;
      const raw = match[0].replace(/\s+/g, " ").trim();
      const page = pageForQuote(doc, match[0].slice(0, 40));
      const citation: Citation = { filename: doc.filename, page, label: spec.name };
      found.push({
        name: spec.name,
        value,
        unit: spec.unit,
        raw,
        sourceKind: doc.kind,
        citation,
      });
      break;
    }
  }
  return found;
}

async function fromWorkbook(doc: IngestedDoc): Promise<Metric[]> {
  if (!/\.xlsx?$/i.test(doc.filename)) return [];
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(doc.path);
  const found: Metric[] = [];
  workbook.eachSheet((sheet) => {
    sheet.eachRow((row) => {
      const label = String(row.getCell(1).text ?? "")
        .trim()
        .toLowerCase();
      const mapped = SHEET_KEYS[label];
      if (!mapped) return;
      const cell = row.getCell(2);
      let value = typeof cell.value === "number" ? cell.value : Number(String(cell.text).replace(/[$,%]/g, ""));
      if (mapped.unit === "pct" && value > 1 && value <= 100) {
        // already percent points
      } else if (mapped.unit === "pct" && value > 0 && value <= 1) {
        value *= 100;
      }
      if (!Number.isFinite(value)) return;
      const citation: Citation = {
        filename: doc.filename,
        sheet: sheet.name,
        label: mapped.name,
      };
      found.push({
        name: mapped.name,
        value,
        unit: mapped.unit,
        raw: `${row.getCell(1).text} ${cell.text}`,
        sourceKind: doc.kind === "other" ? "financials" : doc.kind,
        citation,
      });
    });
  });
  return found;
}

export async function extractMetrics(docs: IngestedDoc[]): Promise<Metric[]> {
  const all: Metric[] = [];
  for (const doc of docs) {
    all.push(...fromMarkdown(doc));
    all.push(...(await fromWorkbook(doc)));
  }
  return all;
}

export function formatMetric(m: Metric): string {
  if (m.unit === "usd") {
    if (m.value >= 1_000_000_000) return `$${(m.value / 1_000_000_000).toFixed(1)}B`;
    if (m.value >= 1_000_000) return `$${(m.value / 1_000_000).toFixed(1)}M`;
    if (m.value >= 1_000) return `$${(m.value / 1_000).toFixed(0)}k`;
    return `$${m.value.toLocaleString("en-US")}`;
  }
  if (m.unit === "pct") return `${m.value}%`;
  if (m.unit === "months") return `${m.value} months`;
  return `${m.value}`;
}

export function pick(metrics: Metric[], name: string, kind?: DocKind): Metric | undefined {
  return metrics.find((m) => m.name === name && (!kind || m.sourceKind === kind));
}

export { citationLabel };

import { citationLabel } from "./paths";
import { formatMetric, pick } from "./metrics";
import type { Deal, DocKind, Flag, Metric } from "./types";

const PAIRS: { name: string; left: DocKind; right: DocKind; quote: string; pageHint?: number }[] = [
  { name: "arr", left: "deck", right: "financials", quote: "$4.2M ARR" },
  { name: "runway_months", left: "deck", right: "financials", quote: "18 months of runway" },
  { name: "headcount", left: "deck", right: "financials", quote: "40 people" },
  { name: "founder_ownership_pct", left: "deck", right: "cap_table", quote: "Founders 15%" },
];

function relDiff(a: number, b: number): number {
  const denom = Math.max(Math.abs(a), Math.abs(b), 1);
  return Math.abs(a - b) / denom;
}

function deckDoc(deal: Deal) {
  return deal.docs.find((d) => d.kind === "deck") ?? deal.docs.find((d) => d.filename.endsWith(".pdf"));
}

function pageFor(deal: Deal, quote: string, fallback?: number): number | null {
  const deck = deckDoc(deal);
  if (!deck) return fallback ?? null;
  const needle = quote.toLowerCase();
  for (const [page, text] of Object.entries(deck.pageTexts)) {
    if (text.toLowerCase().includes(needle)) return Number(page);
  }
  return fallback ?? null;
}

export function runChecklist(deal: Deal, metrics: Metric[]): Flag[] {
  const flags: Flag[] = [];
  const deck = deckDoc(deal);
  const deckId = deck?.docId ?? "deck";

  for (const pair of PAIRS) {
    const left = pick(metrics, pair.name, pair.left);
    const right = pick(metrics, pair.name, pair.right);
    if (!left || !right) continue;
    if (relDiff(left.value, right.value) < 0.08) continue;
    flags.push({
      id: `flag-${pair.name}`,
      docId: deckId,
      page: left.citation.page ?? pageFor(deal, pair.quote),
      type: "highlight",
      severity: "contradiction",
      metric: pair.name,
      quote: pair.quote,
      comment: `Deck claims ${formatMetric(left)}; ${pair.right.replace("_", " ")} show ${formatMetric(right)}.`,
      sourceCitation: citationLabel(right.citation),
    });
  }

  const tam = pick(metrics, "tam", "deck");
  const tamSupport = metrics.find((m) => m.name === "tam" && m.sourceKind !== "deck");
  if (tam && !tamSupport) {
    flags.push({
      id: "flag-tam",
      docId: deckId,
      page: tam.citation.page ?? pageFor(deal, "$48B TAM", 7),
      type: "note",
      severity: "unsupported",
      metric: "tam",
      quote: "$48B TAM",
      comment: `Deck cites ${formatMetric(tam)}. No supporting market study or model line sits in the data room.`,
      sourceCitation: "no supporting document",
    });
  }

  const kinds = new Set(deal.docs.map((d) => d.kind));
  if (!kinds.has("cap_table")) {
    flags.push({
      id: "flag-missing-cap",
      docId: deckId,
      page: null,
      type: "note",
      severity: "missing",
      quote: "",
      comment: "No cap table in the data room. Ownership and dilution claims cannot be reconciled.",
      sourceCitation: "data room",
    });
  }

  const hasCohort = deal.docs.some((d) => /cohort|unit economics|nrr/i.test(d.markdown));
  if (!hasCohort) {
    flags.push({
      id: "flag-missing-cohorts",
      docId: deckId,
      page: null,
      type: "note",
      severity: "missing",
      quote: "",
      comment: "No cohort or unit-economics exhibit. Retention quality is asserted, not shown.",
      sourceCitation: "data room",
    });
  }

  return flags;
}

export function riskScore(flags: Flag[]): number {
  let score = 18;
  for (const flag of flags) {
    if (flag.severity === "contradiction") score += 16;
    else if (flag.severity === "unsupported") score += 8;
    else score += 4;
  }
  return Math.min(96, score);
}

import { formatMetric } from "./metrics";
import type { Flag, KnowledgeGraph, Metric } from "./types";

export function buildGraph(company: string, metrics: Metric[], flags: Flag[]): KnowledgeGraph {
  const nodes: KnowledgeGraph["nodes"] = [
    { id: "company", type: "Company", label: company || "Company" },
  ];
  const edges: KnowledgeGraph["edges"] = [];

  for (const metric of metrics) {
    const id = `${metric.name}:${metric.sourceKind}`;
    if (!nodes.some((n) => n.id === id)) {
      nodes.push({
        id,
        type: "Metric",
        label: metric.name.replaceAll("_", " "),
        value: formatMetric(metric),
        source: metric.sourceKind,
      });
    }
    edges.push({
      source: "company",
      target: id,
      rel: `stated_in_${metric.sourceKind}`,
    });
  }

  for (const flag of flags) {
    const id = `finding:${flag.id}`;
    nodes.push({
      id,
      type: "Finding",
      label: flag.severity,
      value: flag.comment,
      severity: flag.severity,
    });
    if (flag.metric) {
      const left = `${flag.metric}:deck`;
      const right = metrics.find(
        (m) => m.name === flag.metric && m.sourceKind !== "deck",
      );
      if (nodes.some((n) => n.id === left)) {
        edges.push({ source: left, target: id, rel: "flagged", severity: flag.severity });
      }
      if (right) {
        edges.push({
          source: id,
          target: `${right.name}:${right.sourceKind}`,
          rel: "supported_by",
          severity: flag.severity,
        });
      }
    } else {
      edges.push({ source: "company", target: id, rel: "gap", severity: flag.severity });
    }
  }

  return { nodes, edges };
}

import { chat, cosine, embed } from "./llm";
import { formatMetric, pick } from "./metrics";
import type { Deal } from "./types";

type Chunk = { id: string; text: string; source: string; vector?: number[] };

function chunkDoc(filename: string, markdown: string): Chunk[] {
  const parts = markdown.split(/\n{2,}/).map((p) => p.trim()).filter((p) => p.length > 40);
  const chunks: Chunk[] = [];
  let buf = "";
  for (const part of parts) {
    buf = buf ? `${buf}\n\n${part}` : part;
    if (buf.length > 500) {
      chunks.push({ id: `${filename}:${chunks.length}`, text: buf.slice(0, 1200), source: filename });
      buf = "";
    }
  }
  if (buf) chunks.push({ id: `${filename}:${chunks.length}`, text: buf.slice(0, 1200), source: filename });
  return chunks;
}

function metricAnswer(deal: Deal, q: string): string | null {
  const n = q.toLowerCase();
  const want = (name: string) => {
    const room = pick(deal.metrics, name, "financials") ?? pick(deal.metrics, name, "cap_table");
    const deck = pick(deal.metrics, name, "deck");
    if (!room && !deck) return null;
    if (room && deck && room.value !== deck.value) {
      return `The data room says ${formatMetric(room)} (${room.citation.filename}${room.citation.sheet ? `, ${room.citation.sheet}` : ""}). The deck says ${formatMetric(deck)}. Use the data-room figure.`;
    }
    const m = room ?? deck!;
    return `${formatMetric(m)}, from ${m.citation.filename}${m.citation.sheet ? ` · ${m.citation.sheet}` : ""}.`;
  };
  if (/burn/.test(n)) return want("burn_monthly");
  if (/runway/.test(n)) return want("runway_months");
  if (/arr|revenue/.test(n)) return want("arr");
  if (/headcount|employee|team/.test(n)) return want("headcount");
  if (/owner|dilut|founder/.test(n)) return want("founder_ownership_pct");
  if (/cash/.test(n)) return want("cash");
  if (/nrr|retention/.test(n)) return want("nrr");
  return null;
}

export async function answerQuery(deal: Deal, question: string): Promise<{ answer: string; sources: string[] }> {
  const direct = metricAnswer(deal, question);
  if (direct) {
    return { answer: direct, sources: deal.metrics.map((m) => m.citation.filename).filter((v, i, a) => a.indexOf(v) === i) };
  }

  const chunks = deal.docs.flatMap((d) => chunkDoc(d.filename, d.markdown)).slice(0, 24);
  let ranked = chunks;
  try {
    const [qVec, ...vecs] = await embed([question, ...chunks.map((c) => c.text)]);
    ranked = chunks
      .map((c, i) => ({ ...c, vector: vecs[i], score: cosine(qVec, vecs[i]) }))
      .sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
      .slice(0, 4);
  } catch {
    ranked = chunks.slice(0, 4);
  }

  const context = ranked.map((c) => `[${c.source}]\n${c.text}`).join("\n\n");
  const flagNotes = deal.flags.map((f) => `- ${f.severity}: ${f.comment}`).join("\n");
  const prose = await chat([
    {
      role: "system",
      content: "You are an associate answering a partner about one deal. Use only the supplied context. Cite the filename. If you do not know, say so.",
    },
    {
      role: "user",
      content: `Question: ${question}\n\nFlags:\n${flagNotes}\n\nContext:\n${context}`,
    },
  ]);

  const answer =
    prose ||
    `I could not reach the local model. From the file set: ${deal.flags[0]?.comment ?? "see the IC memo."}`;
  return { answer, sources: ranked.map((c) => c.source) };
}

import { chat } from "./llm";
import { formatMetric, pick } from "./metrics";
import { riskScore } from "./checklist";
import type { Deal, Memo } from "./types";

function verdictFor(score: number): string {
  if (score >= 70) return "Do not take to IC without a rebuild of the numbers.";
  if (score >= 50) return "Hold. Partner time only after the four contradictions are closed.";
  return "Proceed to a partner skim; keep the flags in the room.";
}

export async function draftMemo(deal: Deal): Promise<Memo> {
  const arrDeck = pick(deal.metrics, "arr", "deck");
  const arrRoom = pick(deal.metrics, "arr", "financials");
  const burn = pick(deal.metrics, "burn_monthly", "financials");
  const cash = pick(deal.metrics, "cash", "financials");
  const runwayDeck = pick(deal.metrics, "runway_months", "deck");
  const runwayRoom = pick(deal.metrics, "runway_months", "financials");
  const score = deal.riskScore ?? riskScore(deal.flags);
  const company = deal.company || "the company";

  const summary = `${company} is selling warehouse autonomy out of Pittsburgh and asking for a Series A on a deck that does not match its own model. ${
    arrDeck && arrRoom
      ? `Reported ARR is ${formatMetric(arrDeck)} on slide 3 and ${formatMetric(arrRoom)} in the financials.`
      : "Revenue is inconsistently stated."
  } ${
    burn && cash
      ? `Cash of ${formatMetric(cash)} against ${formatMetric(burn)} monthly burn is ${runwayRoom ? formatMetric(runwayRoom) : "under a year"} of runway, not the ${runwayDeck ? formatMetric(runwayDeck) : "18 months"} on the raise slide.`
      : ""
  } Ownership and headcount are also off. This is a first-pass pass-back, not a pass.`;

  const flaggedItems = deal.flags.filter((f) => f.severity !== "missing").map((f) => f.comment);
  const openQuestions = [
    "Which ARR definition is the company using, and can they restate last-twelve-month revenue against the model?",
    "What is the hiring plan if cash only covers nine months at current burn?",
    "Please send the fully-diluted cap table that produces the 15% founder figure — or correct the slide.",
    "Is there a third-party market study behind the $48B TAM, or is that a top-down slide?",
  ];

  const body = [
    `## ${company}`,
    ``,
    `Risk ${score} / 100. ${verdictFor(score)}`,
    ``,
    summary,
    ``,
    `### Flagged items`,
    ...flaggedItems.map((item) => `- ${item}`),
    ``,
    `### Open questions`,
    ...openQuestions.map((item) => `- ${item}`),
  ].join("\n");

  const polish = await chat(
    [
      {
        role: "system",
        content: "Rewrite this IC memo opening in two tight sentences. Do not add facts. No preamble.",
      },
      { role: "user", content: summary },
    ],
    { maxTokens: 180 },
  );

  return {
    title: `First-pass memo · ${company}`,
    company,
    riskScore: score,
    verdict: verdictFor(score),
    summary: polish || summary,
    flaggedItems,
    openQuestions,
    bodyMarkdown: body,
  };
}

import { copyFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { PDFDocument, rgb, StandardFonts } from "pdf-lib";
import { readFile, writeFile } from "node:fs/promises";
import type { Deal } from "./types";

const COLORS = {
  contradiction: rgb(0.706, 0.137, 0.094),
  unsupported: rgb(0.604, 0.404, 0),
  missing: rgb(0.4, 0.44, 0.52),
};

export async function annotateDeck(deal: Deal, outDir: string): Promise<string | null> {
  const deck = deal.docs.find((d) => d.kind === "deck" && d.path.endsWith(".pdf"));
  if (!deck) return null;
  await mkdir(outDir, { recursive: true });
  const dest = path.join(outDir, "deck.annotated.pdf");
  const bytes = await readFile(deck.path);
  const pdf = await PDFDocument.load(bytes);
  const font = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);

  const byPage = new Map<number, typeof deal.flags>();
  for (const flag of deal.flags) {
    if (!flag.page) continue;
    const list = byPage.get(flag.page) ?? [];
    list.push(flag);
    byPage.set(flag.page, list);
  }

  for (const [pageNumber, flags] of byPage) {
    const page = pdf.getPage(pageNumber - 1);
    if (!page) continue;
    const { width, height } = page.getSize();
    let y = height - 36;
    for (const flag of flags) {
      const color = COLORS[flag.severity];
      page.drawRectangle({
        x: 0,
        y: 0,
        width: 8,
        height,
        color,
        opacity: 0.92,
      });
      const label = flag.severity.toUpperCase();
      const boxW = Math.min(320, width * 0.42);
      const text = `${label}  ${flag.comment}`;
      const wrapped = wrap(text, 54);
      const boxH = 16 + wrapped.length * 10;
      page.drawRectangle({
        x: width - boxW - 16,
        y: y - boxH,
        width: boxW,
        height: boxH,
        color: rgb(0.97, 0.96, 0.93),
        opacity: 0.94,
        borderColor: color,
        borderWidth: 1,
      });
      page.drawText(label, {
        x: width - boxW - 8,
        y: y - 12,
        size: 7,
        font: bold,
        color,
      });
      wrapped.forEach((line, i) => {
        page.drawText(line, {
          x: width - boxW - 8,
          y: y - 24 - i * 10,
          size: 7,
          font,
          color: rgb(0.12, 0.14, 0.18),
        });
      });
      y -= boxH + 8;
    }
  }

  await writeFile(dest, await pdf.save());
  const raw = path.join(outDir, path.basename(deck.path));
  await copyFile(deck.path, raw);
  return dest;
}

function wrap(text: string, width: number): string[] {
  const words = text.split(/\s+/);
  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    const next = line ? `${line} ${word}` : word;
    if (next.length > width) {
      if (line) lines.push(line);
      line = word;
    } else line = next;
  }
  if (line) lines.push(line);
  return lines.slice(0, 5);
}

import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { dirs } from "./paths";
import type { Deal, DealSummary } from "./types";

function dealPath(id: string) {
  return path.join(dirs().data, id, "deal.json");
}

export function summarize(deal: Deal): DealSummary {
  const flagCounts = { contradiction: 0, unsupported: 0, missing: 0 };
  for (const flag of deal.flags) flagCounts[flag.severity] += 1;
  return {
    id: deal.id,
    name: deal.name,
    company: deal.company,
    status: deal.status,
    createdAt: deal.createdAt,
    updatedAt: deal.updatedAt,
    riskScore: deal.riskScore,
    flagCounts,
    docCount: deal.docs.length,
    error: deal.error,
    deckFilename: deal.deckFilename,
  };
}

export async function saveDeal(deal: Deal): Promise<void> {
  const folder = path.join(dirs().data, deal.id);
  await mkdir(folder, { recursive: true });
  const slim = {
    ...deal,
    docs: deal.docs.map((d) => ({ ...d, markdown: d.markdown.slice(0, 20000) })),
  };
  await writeFile(dealPath(deal.id), JSON.stringify(slim, null, 2));
  const out = path.join(dirs().outbox, deal.id);
  await mkdir(out, { recursive: true });
  await writeFile(path.join(out, "deal.json"), JSON.stringify(summarize(deal), null, 2));
  if (deal.memo) {
    await writeFile(path.join(out, "memo.md"), deal.memo.bodyMarkdown);
  }
  await writeFile(path.join(out, "flags.json"), JSON.stringify(deal.flags, null, 2));
}

export async function loadDeal(id: string): Promise<Deal | null> {
  try {
    const raw = await readFile(dealPath(id), "utf8");
    return JSON.parse(raw) as Deal;
  } catch {
    return null;
  }
}

export async function listDeals(): Promise<DealSummary[]> {
  await mkdir(dirs().data, { recursive: true });
  const ids = await readdir(dirs().data);
  const deals: DealSummary[] = [];
  for (const id of ids) {
    const deal = await loadDeal(id);
    if (deal) deals.push(summarize(deal));
  }
  return deals.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

import { randomUUID } from "node:crypto";
import path from "node:path";
