import { riskScore, runChecklist } from "./checklist";
import { buildGraph } from "./graph";
import { ingestFolder } from "./ingest";
import { draftMemo } from "./memo";
import { extractMetrics } from "./metrics";
import { dirs } from "./paths";
import { saveDeal } from "./store";
import type { Deal, DealEvent } from "./types";

function slug(name: string) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40);
}

function guessCompany(folder: string, files: string[]): string {
  const fromName = path.basename(folder).replace(/[-_]/g, " ");
  if (fromName && fromName !== "northstar") {
    return fromName.replace(/\b\w/g, (c) => c.toUpperCase());
  }
  const deck = files.find((f) => /northstar/i.test(f));
  return deck ? "Northstar Robotics" : fromName || "Untitled deal";
}

export async function runDeal(sourcePath: string, name?: string): Promise<Deal> {
  const now = new Date().toISOString();
  const id = `${slug(name || path.basename(sourcePath))}-${randomUUID().slice(0, 8)}`;
  const events: DealEvent[] = [];
  const push = (stage: DealEvent["stage"], message: string) => {
    events.push({ at: new Date().toISOString(), stage, message });
  };

  const deal: Deal = {
    id,
    name: name || path.basename(sourcePath),
    company: "",
    status: "ingesting",
    createdAt: now,
    updatedAt: now,
    sourcePath,
    docs: [],
    metrics: [],
    flags: [],
    graph: { nodes: [], edges: [] },
    events,
  };

  try {
    push("ingest", "Reading the data room");
    deal.docs = await ingestFolder(sourcePath);
    deal.company = guessCompany(sourcePath, deal.docs.map((d) => d.filename));
    deal.deckFilename = deal.docs.find((d) => d.kind === "deck")?.filename;
    deal.status = "graphing";
    deal.updatedAt = new Date().toISOString();
    await saveDeal(deal);

    push("graph", "Extracting numbers and linking sources");
    deal.metrics = await extractMetrics(deal.docs);
    deal.status = "diligence";
    await saveDeal(deal);

    push("diligence", "Cross-checking the deck against the financials");
    deal.flags = runChecklist(deal, deal.metrics);
    deal.riskScore = riskScore(deal.flags);
    deal.graph = buildGraph(deal.company, deal.metrics, deal.flags);

    deal.status = "annotating";
    push("annotate", "Marking the deck and drafting the memo");
    deal.memo = await draftMemo(deal);
    await annotateDeck(deal, path.join(dirs().outbox, deal.id));

    deal.status = "ready";
    deal.updatedAt = new Date().toISOString();
    push("ready", `${deal.flags.length} findings · risk ${deal.riskScore}`);
    await saveDeal(deal);
    return deal;
  } catch (error) {
    deal.status = "error";
    deal.error = (error as Error).message;
    deal.updatedAt = new Date().toISOString();
    push("error", deal.error);
    await saveDeal(deal);
    throw error;
  }
}

