import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { NextResponse } from "next/server";
import { dirs } from "@/lib/diligence/paths";
import { runDeal } from "@/lib/diligence/pipeline";

export async function POST(request: Request) {
  const form = await request.formData();
  const files = form.getAll("files").filter((f): f is File => f instanceof File);
  if (!files.length) return NextResponse.json({ error: "no files" }, { status: 400 });
  const name = String(form.get("name") || files[0].name.replace(/\.[^.]+$/, "") || "deal");
  const folder = path.join(dirs().inbox, `${name.replace(/[^\w.-]+/g, "-")}-${Date.now()}`);
  await mkdir(folder, { recursive: true });
  for (const file of files) {
    const buf = Buffer.from(await file.arrayBuffer());
    await writeFile(path.join(folder, file.name), buf);
  }
  const deal = await runDeal(folder, name);
  return NextResponse.json({ id: deal.id, status: deal.status });
}

