"use client";

import { useEffect, useRef, useState } from "react";
import type { Flag } from "@/lib/diligence/types";

type Props = {
  src: string;
  flags: Flag[];
  activeId?: string | null;
  onPage?: (page: number) => void;
};

export function DeckViewer({ src, flags, activeId, onPage }: Props) {
  const host = useRef<HTMLDivElement>(null);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    let dead = false;
    async function render() {
      if (!host.current) return;
      host.current.innerHTML = "";
      try {
        const pdfjs = await import("pdfjs-dist");
        pdfjs.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;
        const pdf = await pdfjs.getDocument(src).promise;
        for (let n = 1; n <= pdf.numPages; n++) {
          if (dead) return;
          const page = await pdf.getPage(n);
          const viewport = page.getViewport({ scale: 1.15 });
          const wrap = document.createElement("section");
          wrap.id = `slide-${n}`;
          wrap.className = "relative mb-6 bg-[#f3eee4]";
          wrap.style.width = `${viewport.width}px`;
          wrap.style.maxWidth = "100%";
          const canvas = document.createElement("canvas");
          canvas.width = viewport.width;
          canvas.height = viewport.height;
          canvas.className = "block h-auto w-full";
          wrap.appendChild(canvas);
          const pageFlags = flags.filter((f) => f.page === n);
          if (pageFlags.length) {
            const bar = document.createElement("div");
            const sev = pageFlags[0].severity;
            bar.className = "absolute inset-y-0 left-0 w-[7px]";
            bar.style.background =
              sev === "contradiction" ? "#b42318" : sev === "unsupported" ? "#9a6700" : "#667085";
            wrap.appendChild(bar);
          }
          host.current.appendChild(wrap);
          const ctx = canvas.getContext("2d");
          if (ctx) await page.render({ canvasContext: ctx, viewport, canvas }).promise;
        }
      } catch (error) {
        setErr((error as Error).message);
      }
    }
    void render();
    return () => {
      dead = true;
    };
  }, [src, flags]);

  useEffect(() => {
    if (!activeId) return;
    const flag = flags.find((f) => f.id === activeId);
    if (!flag?.page) return;
    document.getElementById(`slide-${flag.page}`)?.scrollIntoView({ behavior: "smooth", block: "start" });
    onPage?.(flag.page);
  }, [activeId, flags, onPage]);

  if (err) {
    return <p className="p-6 text-sm text-flag-red">Could not render the deck. {err}</p>;
  }
  return <div ref={host} className="px-6 py-6" />;
}

"use client";

import type { KnowledgeGraph } from "@/lib/diligence/types";

const COLOR: Record<string, string> = {
  Company: "#f3eee4",
  Metric: "#8b5e3c",
  Finding: "#b42318",
};

export function GraphView({ graph }: { graph: KnowledgeGraph }) {
  const company = graph.nodes.find((n) => n.type === "Company");
  const metrics = graph.nodes.filter((n) => n.type === "Metric");
  const findings = graph.nodes.filter((n) => n.type === "Finding");
  const width = 520;
  const height = 360;
  const cx = 260;
  const cy = 170;

  const metricPos = metrics.map((node, i) => {
    const t = (i / Math.max(metrics.length, 1)) * Math.PI + Math.PI * 0.15;
    return { node, x: 90 + Math.cos(t) * 30, y: 50 + i * (280 / Math.max(metrics.length, 1)) };
  });
  const findPos = findings.map((node, i) => {
    return { node, x: 430, y: 50 + i * (280 / Math.max(findings.length, 1)) };
  });

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="h-[360px] w-full">
      {metricPos.map(({ node, x, y }) => (
        <line key={`e-${node.id}`} x1={cx} y1={cy} x2={x + 70} y2={y} stroke="#2a333d" />
      ))}
      {findPos.map(({ node, x, y }) => (
        <line
          key={`f-${node.id}`}
          x1={cx}
          y1={cy}
          x2={x}
          y2={y}
          stroke={node.severity === "contradiction" ? "#b42318" : "#9a6700"}
          strokeDasharray="3 3"
        />
      ))}
      <circle cx={cx} cy={cy} r="28" fill="#16202b" stroke="#f3eee4" />
