          />
          <text x={x} y={y + 5} fill="#e7edf2" fontSize="9">
            {node.label}
          </text>
        </g>
      ))}
    </svg>
  );
}

"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import type { Deal } from "@/lib/diligence/types";
import { riskTone } from "@/lib/format";
import { DeckViewer } from "./DeckViewer";
import { GraphView } from "./GraphView";

const SEV = {
  contradiction: { label: "Contradiction", color: "text-flag-red", rule: "border-flag-red" },
  unsupported: { label: "Unsupported", color: "text-flag-amber", rule: "border-flag-amber" },
  missing: { label: "Missing", color: "text-flag-gray", rule: "border-flag-gray" },
};

export function DealDesk({ deal }: { deal: Deal }) {
  const [active, setActive] = useState<string | null>(deal.flags[0]?.id ?? null);
  const [tab, setTab] = useState<"memo" | "graph" | "ask">("memo");
  const [question, setQuestion] = useState("What's their real burn?");
  const [answer, setAnswer] = useState<string | null>(null);
  const [sources, setSources] = useState<string[]>([]);
  const [asking, setAsking] = useState(false);

  const sorted = useMemo(
    () =>
      [...deal.flags].sort((a, b) => {
        const order = { contradiction: 0, unsupported: 1, missing: 2 };
        return order[a.severity] - order[b.severity] || (a.page ?? 99) - (b.page ?? 99);
      }),
    [deal.flags],
  );

  async function ask() {
    setAsking(true);
    const res = await fetch(`/api/deals/${deal.id}/query`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
    });
    const data = await res.json();
    setAnswer(data.answer);
    setSources(data.sources ?? []);
    setAsking(false);
  }

  return (
    <div className="flex h-screen flex-col bg-desk text-paper">
      <header className="flex items-center justify-between border-b border-white/10 px-5 py-3">
        <div className="flex items-baseline gap-4">
          <Link href="/" className="font-mono text-[12px] text-copper">
            Night Desk
          </Link>
          <h1 className="font-serif text-2xl">{deal.company}</h1>
        </div>
        <div className="flex items-baseline gap-6 font-mono text-[12px]">
          <span className={riskTone(deal.riskScore)}>risk {deal.riskScore ?? "—"}</span>
          <span className="text-paper/45">{deal.status}</span>
          <a href={`/api/deals/${deal.id}/deck`} className="text-paper/70 hover:text-paper">
            original pdf
          </a>
        </div>
      </header>

      <div className="grid min-h-0 flex-1 grid-cols-[280px_minmax(0,1.15fr)_minmax(320px,0.95fr)]">
        <aside className="min-h-0 overflow-y-auto border-r border-white/10">
          <p className="px-4 pt-4 font-mono text-[11px] text-paper/40">On the slides</p>
          <ul>
            {sorted.map((flag) => {
              const meta = SEV[flag.severity];
              const on = active === flag.id;
              return (
                <li key={flag.id}>
                  <button
                    type="button"
                    onClick={() => setActive(flag.id)}
                    className={`w-full border-l-2 px-4 py-3 text-left ${meta.rule} ${on ? "bg-white/6" : ""}`}
                  >
                    <div className="flex items-baseline justify-between gap-3">
                      <span className={`font-mono text-[11px] ${meta.color}`}>{meta.label}</span>
                      <span className="font-mono text-[11px] text-paper/40">
                        {flag.page ? `slide ${flag.page}` : "room"}
                      </span>
                    </div>
                    <p className="mt-1 text-[13px] leading-5 text-paper/85">{flag.comment}</p>
                    <p className="mt-1 font-mono text-[10px] text-paper/40">{flag.sourceCitation}</p>
                  </button>
                </li>
              );
            })}
          </ul>
        </aside>

        <main className="min-h-0 overflow-y-auto bg-[#d8dee4]">
          <DeckViewer src={`/api/deals/${deal.id}/deck`} flags={deal.flags} activeId={active} />
        </main>

        <section className="flex min-h-0 flex-col bg-memo text-ink">
          <div className="flex border-b border-black/10 font-mono text-[11px]">
            {(["memo", "graph", "ask"] as const).map((key) => (
              <button
                key={key}
                type="button"
                onClick={() => setTab(key)}
                className={`px-4 py-3 ${tab === key ? "text-ink" : "text-ink/40"}`}
              >
                {key === "memo" ? "IC memo" : key === "graph" ? "Graph" : "Ask"}
              </button>
            ))}
          </div>
          <div className="min-h-0 flex-1 overflow-y-auto px-6 py-5">
            {tab === "memo" && deal.memo && (
              <article>
                <p className="font-mono text-[11px] text-copper">{deal.memo.verdict}</p>
                <div
                  className="memo-body mt-4 font-serif text-[16px] leading-7"
                  dangerouslySetInnerHTML={{
                    __html: md(deal.memo.bodyMarkdown),
                  }}
                />
              </article>
            )}
            {tab === "graph" && (
              <div>
                <p className="mb-3 text-sm leading-6 text-ink/70">
                  Claims on the left, data-room numbers in copper, findings on the right. Red links are contradictions.
                </p>
                <GraphView graph={deal.graph} />
                <ul className="mt-4 space-y-2 font-mono text-[11px] text-ink/70">
                  {deal.metrics.map((m) => (
                    <li key={`${m.name}-${m.sourceKind}`}>
                      {m.name.replaceAll("_", " ")} · {m.sourceKind} · {m.raw}
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {tab === "ask" && (
              <div>
                <p className="text-sm leading-6 text-ink/70">
                  Ask against this deal. Metric questions read the table first; everything else goes through local RAG.
                </p>
                <textarea
                  value={question}
                  onChange={(e) => setQuestion(e.target.value)}
                  className="mt-4 h-24 w-full border border-black/15 bg-white/40 p-3 text-sm outline-none"
                />
                <button
                  type="button"
                  onClick={ask}
                  disabled={asking}
                  className="mt-3 bg-ink px-4 py-2 text-sm text-paper disabled:opacity-50"
                >
                  {asking ? "Looking…" : "Ask the room"}
                </button>
                {answer && (
                  <div className="mt-5 font-serif text-[16px] leading-7">
                    {answer}
                    {sources.length > 0 && (
                      <p className="mt-3 font-mono text-[11px] text-ink/45">src {sources.join(" · ")}</p>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
}

function md(src: string): string {
  return src
    .replace(/^### (.*)$/gm, "<h3>$1</h3>")
    .replace(/^## (.*)$/gm, "<h2>$1</h2>")
    .replace(/^- (.*)$/gm, "<li>$1</li>")
    .replace(/(<li>.*<\/li>\n?)+/g, "<ul>$&</ul>")
    .replace(/\n{2,}/g, "<p></p>");
}

