import { cp, mkdir, readdir, stat } from "node:fs/promises";
import path from "node:path";
import { dirs } from "./paths";
import type { DealSandbox } from "./types";

export function dealRoot(dealId: string) {
  return path.resolve(dirs().data, dealId);
}

export function assertInsideDeal(dealId: string, filePath: string): string {
  const root = dealRoot(dealId);
  const resolved = path.resolve(filePath);
  if (resolved !== root && !resolved.startsWith(root + path.sep)) {
    throw new Error("Path is outside this deal's room");
  }
  return resolved;
}

async function copyInto(source: string, dest: string) {
  const info = await stat(source);
  await mkdir(dest, { recursive: true });
  if (info.isFile()) {
    await cp(source, path.join(dest, path.basename(source)));
    return;
  }
  const entries = await readdir(source, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name.startsWith(".")) continue;
    await cp(path.join(source, entry.name), path.join(dest, entry.name), {
      recursive: true,
      dereference: true,
    });
  }
}

export async function isolateDeal(dealId: string, sourcePath: string): Promise<DealSandbox> {
  const root = dealRoot(dealId);
  const workspace = path.join(root, "workspace");
  const source = path.resolve(sourcePath);
  const dataRoot = path.resolve(dirs().data);

  if (source.startsWith(dataRoot + path.sep) && !source.startsWith(root + path.sep)) {
    throw new Error("Refusing to copy files from another deal");
  }

  await copyInto(source, workspace);
  return { kind: "local", root, workspace };
}

import { citationLabel } from "./paths";
import { formatMetric, pick } from "./metrics";
import type { Flag, KnowledgeGraph, Metric, ReconcileRow, ReconcileStatus } from "./types";

const LABELS: Record<string, string> = {
  arr: "Annual recurring revenue",
  runway_months: "Runway",
  headcount: "Headcount",
  founder_ownership_pct: "Founder ownership",
  burn_monthly: "Monthly burn",
  cash: "Cash on hand",
  tam: "Market size",
  nrr: "Net revenue retention",
  raise: "The ask",
};

const ROW_ORDER: ReconcileStatus[] = [
  "contradiction",
  "unsupported",
  "gap",
  "deck-only",
  "room-only",
  "match",
];

const METRIC_ORDER = Object.keys(LABELS);

export function buildReconcile(metrics: Metric[], flags: Flag[]): ReconcileRow[] {
  const names = new Set<string>();
  for (const metric of metrics) names.add(metric.name);
  for (const flag of flags) {
    if (flag.metric) names.add(flag.metric);
  }

  const flagByMetric = new Map<string, Flag>();
  for (const flag of flags) {
    if (flag.metric && !flagByMetric.has(flag.metric)) flagByMetric.set(flag.metric, flag);
  }

  const rows: ReconcileRow[] = [];
  for (const name of names) {
    const deck = pick(metrics, name, "deck");
    const room = metrics.find((m) => m.name === name && m.sourceKind !== "deck");
    const flag = flagByMetric.get(name);
    let status: ReconcileStatus;
    if (flag?.severity === "contradiction") status = "contradiction";
    else if (flag?.severity === "unsupported") status = "unsupported";
    else if (deck && room) status = "match";
    else if (deck) status = "deck-only";
    else status = "room-only";

    rows.push({
      metric: name,
      label: LABELS[name] ?? name.replaceAll("_", " "),
      deck: deck ? formatMetric(deck) : undefined,
      room: room ? formatMetric(room) : undefined,
      roomSource: room ? citationLabel(room.citation) : undefined,
      status,
      comment: flag?.comment,
      flagId: flag?.id,
      page: deck?.citation.page ?? flag?.page ?? null,
    });
  }

  for (const flag of flags) {
    if (flag.metric) continue;
    rows.push({
      metric: flag.id,
      label: "Missing from the room",
      status: "gap",
      comment: flag.comment,
      flagId: flag.id,
      page: flag.page,
    });
  }

  return rows.sort((a, b) => {
    const byStatus = ROW_ORDER.indexOf(a.status) - ROW_ORDER.indexOf(b.status);
    if (byStatus !== 0) return byStatus;
    return METRIC_ORDER.indexOf(a.metric) - METRIC_ORDER.indexOf(b.metric);
  });
}

export function buildGraph(company: string, metrics: Metric[], flags: Flag[]): KnowledgeGraph {
  return {
    nodes: [{ id: "company", type: "Company", label: company || "Company" }],
    edges: [],
    rows: buildReconcile(metrics, flags),
  };
}

import { buildReconcile } from "./graph";
import type { Deal, DealRoomView } from "./types";

export function toRoomView(deal: Deal): DealRoomView {
  return {
    id: deal.id,
    name: deal.name,
    company: deal.company,
    status: deal.status,
    riskScore: deal.riskScore,
    sandbox: deal.sandbox,
    flags: deal.flags,
    memo: deal.memo
      ? { verdict: deal.memo.verdict, bodyMarkdown: deal.memo.bodyMarkdown }
      : undefined,
    reconcile: deal.graph.rows?.length ? deal.graph.rows : buildReconcile(deal.metrics, deal.flags),
    files: deal.docs.map((doc) => ({ filename: doc.filename, kind: doc.kind })),
  };
}

