"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useRef, useState, useTransition } from "react";
import type { DealSummary } from "@/lib/diligence/types";
import { riskTone, when } from "@/lib/format";

type Props = {
  deals: DealSummary[];
  model: { ok: boolean; models: string[] };
};

export function DealPicker({ deals, model }: Props) {
  const router = useRouter();
  const input = useRef<HTMLInputElement>(null);
  const [pending, startTransition] = useTransition();
  const [kind, setKind] = useState<"sample" | "upload" | null>(null);
  const [name, setName] = useState("");
  const [error, setError] = useState<string | null>(null);
  const busy = pending || kind !== null;

  function runSample() {
    setKind("sample");
    setError(null);
    startTransition(async () => {
      const res = await fetch("/api/deals/sample", { method: "POST" });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? "Could not open the sample room");
        setKind(null);
        return;
      }
      router.push(`/deals/${data.id}`);
      router.refresh();
    });
  }

  function onFiles(files: FileList | null) {
    if (!files?.length) return;
    setKind("upload");
    setError(null);
    const form = new FormData();
    if (name.trim()) form.append("name", name.trim());
    for (const file of files) form.append("files", file);
    startTransition(async () => {
      const res = await fetch("/api/deals/upload", { method: "POST", body: form });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? "Could not start this deal");
        setKind(null);
        return;
      }
      router.push(`/deals/${data.id}`);
      router.refresh();
    });
  }

  return (
    <div className="min-h-screen bg-desk text-paper">
      <header className="mx-auto flex max-w-5xl items-end justify-between px-8 pb-10 pt-14">
        <div>
          <p className="font-mono text-[13px] text-copper">Night Desk</p>
          <h1 className="mt-2 font-serif text-5xl font-medium tracking-tight">Open a deal</h1>
          <p className="mt-3 max-w-md text-[15px] leading-6 text-paper/60">
            Pick a room you already started, or make a new one. Each deal keeps its own files.
          </p>
        </div>
        <p className="font-mono text-[11px] text-paper/40">
          {model.ok ? `local · ${model.models[0] ?? "ollama"}` : "ollama not reachable"}
        </p>
      </header>

      <div className="mx-auto grid max-w-5xl gap-16 px-8 pb-20 md:grid-cols-[1.15fr_0.85fr]">
        <section>
          <h2 className="text-[15px] text-paper/70">Your rooms</h2>
          {deals.length === 0 ? (
            <p className="mt-8 max-w-sm text-[15px] leading-7 text-paper/45">
              Nothing here yet. Start with the Northstar sample — a made-up robotics company with a
              few numbers that do not line up.
            </p>
          ) : (
            <ul className="mt-4">
              {deals.map((deal) => {
                const checks = deal.flagCounts.contradiction + deal.flagCounts.unsupported;
                return (
                  <li key={deal.id} className="deal-row">
                    <Link href={`/deals/${deal.id}`} className="block py-5">
                      <div className="flex items-baseline justify-between gap-6">
                        <h3 className="font-serif text-[28px] leading-none">
                          {deal.company || deal.name}
                        </h3>
                        <span className={`font-mono text-[12px] ${riskTone(deal.riskScore)}`}>
                          {deal.riskScore != null ? `risk ${deal.riskScore}` : deal.status}
                        </span>
                      </div>
                      <p className="mt-2 text-[14px] text-paper/50">
                        {checks > 0
                          ? `${checks} ${checks === 1 ? "thing" : "things"} to check`
                          : "First pass is in"}
                        <span className="mx-2 text-paper/25">·</span>
                        {deal.docCount} {deal.docCount === 1 ? "file" : "files"}
                        <span className="mx-2 text-paper/25">·</span>
                        {when(deal.createdAt)}
                      </p>
                    </Link>
                  </li>
                );
              })}
            </ul>
          )}
        </section>

        <aside>
          <h2 className="text-[15px] text-paper/70">Start a new one</h2>
          <p className="mt-3 text-[14px] leading-6 text-paper/50">
            Give it a name if you like, then drop the deck and the data room. Night Desk copies those
            files into a sealed folder and reads only that folder.
          </p>
          <label className="mt-6 block">
            <span className="font-mono text-[11px] text-paper/40">Company or deal name</span>
            <input
              value={name}
              onChange={(event) => setName(event.target.value)}
              placeholder="Northstar Robotics"
              className="mt-2 w-full border-b border-white/15 bg-transparent py-2 text-[16px] outline-none placeholder:text-paper/25 focus:border-copper"
            />
          </label>
          <button
            type="button"
            onClick={() => input.current?.click()}
            disabled={busy}
            className="mt-6 w-full border border-dashed border-white/18 px-5 py-10 text-left text-[15px] leading-6 text-paper/70 hover:border-copper hover:text-paper disabled:opacity-50"
          >
            Drop the deck and supporting files
            <span className="mt-1 block font-mono text-[11px] text-paper/40">
              pdf, pptx, xlsx, docx — or click to choose
            </span>
          </button>
          <input
            ref={input}
            type="file"
            multiple
            className="hidden"
            onChange={(event) => onFiles(event.target.files)}
          />
          <button
            type="button"
            onClick={runSample}
            disabled={busy}
            className="mt-4 w-full bg-paper px-5 py-3.5 text-left text-[15px] text-ink hover:bg-white disabled:opacity-50"
          >
            {kind === "sample" ? "Opening Northstar…" : "Try the Northstar sample"}
          </button>
          {kind === "upload" ? (
            <p className="mt-4 text-[14px] text-copper">Reading the room…</p>
          ) : null}
          {error ? <p className="mt-4 text-[14px] text-flag-red">{error}</p> : null}
        </aside>
      </div>
    </div>
  );
}

import type { Flag } from "@/lib/diligence/types";

const SEV = {
  contradiction: { label: "Doesn't match", color: "text-flag-red", rule: "border-flag-red" },
  unsupported: { label: "Only on the deck", color: "text-flag-amber", rule: "border-flag-amber" },
  missing: { label: "Missing", color: "text-flag-gray", rule: "border-flag-gray" },
};

const ORDER = { contradiction: 0, unsupported: 1, missing: 2 };

type Props = {
  flags: Flag[];
  activeId: string | null;
  onSelect: (id: string) => void;
};

export function FlagList({ flags, activeId, onSelect }: Props) {
  const sorted = flags.toSorted(
    (a, b) => ORDER[a.severity] - ORDER[b.severity] || (a.page ?? 99) - (b.page ?? 99),
  );

  return (
    <aside className="min-h-0 overflow-y-auto border-r border-white/10">
      <p className="px-5 pt-5 text-[13px] text-paper/45">On the slides</p>
      {sorted.length === 0 ? (
        <p className="px-5 py-6 text-[14px] leading-6 text-paper/40">No flags on this deck yet.</p>
      ) : (
        <ul>
          {sorted.map((flag) => {
            const meta = SEV[flag.severity];
            const on = activeId === flag.id;
            return (
              <li key={flag.id} className="flag-row">
                <button
                  type="button"
                  onClick={() => onSelect(flag.id)}
                  className={`w-full border-l-2 px-5 py-4 text-left ${meta.rule} ${on ? "bg-white/6" : ""}`}
                >
                  <div className="flex items-baseline justify-between gap-3">
                    <span className={`font-mono text-[11px] ${meta.color}`}>{meta.label}</span>
                    <span className="font-mono text-[11px] text-paper/35">
                      {flag.page ? `slide ${flag.page}` : "room"}
                    </span>
                  </div>
                  <p className="mt-1.5 text-[14px] leading-5 text-paper/85">{flag.comment}</p>
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </aside>
  );
}

type Props = {
  verdict?: string;
  bodyMarkdown?: string;
};

function memoHtml(src: string): string {
  return src
    .replace(/^### (.*)$/gm, "<h3>$1</h3>")
    .replace(/^## (.*)$/gm, "<h2>$1</h2>")
    .replace(/^- (.*)$/gm, "<li>$1</li>")
    .replace(/(<li>.*<\/li>\n?)+/g, "<ul>$&</ul>")
    .replace(/\n{2,}/g, "<p></p>");
}

export function MemoPanel({ verdict, bodyMarkdown }: Props) {
  if (!bodyMarkdown) {
    return <p className="text-[15px] leading-7 text-ink/55">The memo is still being written.</p>;
  }

  return (
    <article className="mx-auto max-w-2xl">
      {verdict ? <p className="font-mono text-[12px] text-copper">{verdict}</p> : null}
      <div
        className="memo-body mt-5 font-serif text-[17px] leading-8"
        dangerouslySetInnerHTML={{ __html: memoHtml(bodyMarkdown) }}
      />
    </article>
  );
}

import type { ReconcileRow, ReconcileStatus } from "@/lib/diligence/types";

const TONE: Record<ReconcileStatus, { label: string; className: string }> = {
  contradiction: { label: "Doesn't match", className: "text-flag-red" },
  unsupported: { label: "Only on the deck", className: "text-flag-amber" },
  gap: { label: "Not in the room", className: "text-flag-gray" },
  "deck-only": { label: "Deck only", className: "text-ink/45" },
  "room-only": { label: "Room only", className: "text-ink/45" },
  match: { label: "Lines up", className: "text-ledger" },
};

type Props = {
  rows: ReconcileRow[];
  activeId: string | null;
  onOpenFlag: (id: string) => void;
};

export function ReconciliationMap({ rows, activeId, onOpenFlag }: Props) {
  return (
    <div className="mx-auto max-w-3xl px-8 py-10">
      <h2 className="font-serif text-3xl text-ink">What the deck says vs the room</h2>
      <p className="mt-3 max-w-xl text-[15px] leading-7 text-ink/60">
        Same number, two sources. Red means the slide and the spreadsheet do not agree. Use the
        data-room figure unless you have a reason not to.
      </p>
      {rows.length === 0 ? (
        <p className="mt-10 text-[15px] text-ink/45">No numbers to compare yet.</p>
      ) : (
        <ol className="mt-10">
          {rows.map((row) => {
            const tone = TONE[row.status];
            const open = row.flagId ? () => onOpenFlag(row.flagId!) : undefined;
            const Tag = open ? "button" : "div";
            return (
              <li key={row.metric} className="recon-row">
                <Tag
                  type={open ? "button" : undefined}
                  onClick={open}
                  className={`w-full py-6 text-left ${row.flagId ? "cursor-pointer" : ""} ${
                    activeId && row.flagId === activeId ? "bg-black/3" : ""
                  }`}
                >
                  <div className="flex items-baseline justify-between gap-4">
                    <h3 className="font-serif text-[22px] text-ink">{row.label}</h3>
                    <span className={`font-mono text-[11px] ${tone.className}`}>{tone.label}</span>
                  </div>
                  <div className="mt-4 grid grid-cols-2 gap-6">
                    <p>
                      <span className="block font-mono text-[11px] text-ink/40">Deck</span>
                      <span className="mt-1 block text-[20px] text-ink">{row.deck ?? "—"}</span>
                      {row.page ? (
                        <span className="mt-1 block font-mono text-[11px] text-ink/40">
                          slide {row.page}
                        </span>
                      ) : null}
                    </p>
                    <p>
                      <span className="block font-mono text-[11px] text-ink/40">Data room</span>
                      <span className="mt-1 block text-[20px] text-ink">{row.room ?? "—"}</span>
                      {row.roomSource ? (
                        <span className="mt-1 block font-mono text-[11px] text-ink/40">
                          {row.roomSource}
                        </span>
                      ) : null}
                    </p>
                  </div>
                  {row.comment ? (
                    <p className="mt-4 max-w-xl text-[14px] leading-6 text-ink/65">{row.comment}</p>
                  ) : null}
                </Tag>
              </li>
            );
          })}
        </ol>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";

type Props = {
  dealId: string;
};

export function AskPanel({ dealId }: Props) {
  const [question, setQuestion] = useState("What's their real burn?");
  const [answer, setAnswer] = useState<string | null>(null);
  const [sources, setSources] = useState<string[]>([]);
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  function ask() {
    setError(null);
    startTransition(async () => {
      const res = await fetch(`/api/deals/${dealId}/query`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? "Could not ask the room");
        return;
      }
      setAnswer(data.answer);
      setSources(data.sources ?? []);
    });
  }

  return (
    <div className="mx-auto max-w-xl px-8 py-10">
      <h2 className="font-serif text-3xl text-ink">Ask this room</h2>
      <p className="mt-3 text-[15px] leading-7 text-ink/60">
        Questions stay inside this deal. Metric questions read the table first.
      </p>
      <textarea
        value={question}
        onChange={(event) => setQuestion(event.target.value)}
        className="mt-6 h-28 w-full border border-black/12 bg-white/50 p-3 text-[15px] leading-6 outline-none focus:border-copper"
      />
      <button
        type="button"
        onClick={ask}
        disabled={pending || !question.trim()}
        className="mt-4 bg-ink px-4 py-2.5 text-[14px] text-paper disabled:opacity-50"
      >
        {pending ? "Looking…" : "Ask"}
      </button>
      {error ? <p className="mt-4 text-[14px] text-flag-red">{error}</p> : null}
      {answer ? (
        <div className="mt-8 font-serif text-[17px] leading-8 text-ink">
          {answer}
          {sources.length > 0 ? (
            <p className="mt-4 font-mono text-[11px] text-ink/40">from {sources.join(" · ")}</p>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

