          </a>
          <a href={`/api/deals/${deal.id}/annotated`} className="hover:text-paper">
            marked pdf
          </a>
        </div>
      </header>

      <nav className="flex gap-1 border-b border-white/10 px-4">
        {TABS.map((item) => (
          <button
            key={item.id}
            type="button"
            onClick={() => setTab(item.id)}
            className={`px-4 py-3 text-[14px] ${tab === item.id ? "text-paper" : "text-paper/40"}`}
          >
            {item.label}
          </button>
        ))}
      </nav>

      <div className="relative min-h-0 flex-1">
