import { formatMetric, pick } from "./metrics";
import { resolveExisting } from "./files";
import { dealRoot } from "./sandbox";
import type { Deal, Flag, FlagView, IngestedDoc, SourcePreview } from "./types";
import path from "node:path";
import { existsSync } from "node:fs";

export const METRIC_LABELS: Record<string, string> = {
  arr: "Annual recurring revenue",
  runway_months: "Runway",
  headcount: "Headcount",
  founder_ownership_pct: "Founder ownership",
  burn_monthly: "Monthly burn",
  cash: "Cash on hand",
  tam: "Market size",
  nrr: "Net revenue retention",
  raise: "The ask",
};

const NEEDLES: Record<string, string[]> = {
  arr: ["arr", "annual recurring"],
  runway_months: ["runway"],
  headcount: ["headcount", "employees"],
  founder_ownership_pct: ["founder ownership", "founders fd", "founders"],
  burn_monthly: ["monthly burn", "burn"],
  cash: ["cash on hand", "cash"],
  tam: ["tam", "addressable"],
  nrr: ["nrr"],
  raise: ["raising", "the ask"],
};

function prettyCell(value: string): string {
  const trimmed = value.replace(/,/g, "").trim();
  if (!/^\d+(\.\d+)?$/.test(trimmed)) return value;
  const n = Number(trimmed);
  if (!Number.isFinite(n)) return value;
  if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 10_000) return n.toLocaleString("en-US");
  return value;
}

function tablesFromMarkdown(markdown: string): { sheet?: string; rows: string[][] }[] {
  const chunks = markdown.split(/^## /m);
  const tables: { sheet?: string; rows: string[][] }[] = [];
  for (const chunk of chunks) {
    const lines = chunk.split("\n");
    const heading = lines[0]?.replace(/<!--.*?-->/g, "").trim();
    const tableLines = lines.filter((line) => line.trim().startsWith("|"));
    if (tableLines.length < 2) continue;
    const rows = tableLines
      .filter((line) => !/^\|\s*[-: ]+\|/.test(line.trim()))
      .map((line) =>
        line
          .split("|")
          .slice(1, -1)
          .map((cell) => cell.trim()),
      )
      .filter((row) => row.some((cell) => cell.length > 0));
    if (!rows.length) continue;
    tables.push({
      sheet: heading && !heading.startsWith("source:") ? heading : undefined,
      rows,
    });
  }
  return tables;
}

function excerptText(markdown: string, highlight?: string): string {
  const clean = markdown.replace(/<!--.*?-->/g, "").replace(/^#+\s+/gm, "").trim();
  if (!highlight) return clean.slice(0, 360);
  const idx = clean.toLowerCase().indexOf(highlight.toLowerCase());
  if (idx < 0) return clean.slice(0, 360);
  const start = Math.max(0, idx - 80);
  return `${start > 0 ? "…" : ""}${clean.slice(start, start + 280).trim()}${clean.length > start + 280 ? "…" : ""}`;
}

function previewDoc(doc: IngestedDoc, metric: string | undefined, highlight?: string, sheet?: string): SourcePreview {
  const needles = [
    ...(metric ? NEEDLES[metric] ?? [metric.replaceAll("_", " ")] : []),
    highlight?.toLowerCase() ?? "",
    sheet?.toLowerCase() ?? "",
  ].filter(Boolean);

  const tables = tablesFromMarkdown(doc.markdown);
  const preferred =
    (sheet && tables.find((table) => table.sheet?.toLowerCase() === sheet.toLowerCase())) ??
    tables.find((table) =>
      table.rows.some((row) => needles.some((needle) => row.join(" ").toLowerCase().includes(needle))),
    ) ??
    tables[0];

  if (preferred?.rows.length) {
    const decorated = preferred.rows.map((cells) => {
      const blob = cells.join(" ").toLowerCase();
      const hit = needles.some((needle) => needle.length > 1 && blob.includes(needle));
      return { cells: cells.map(prettyCell), hit };
    });
    if (!decorated.some((row) => row.hit) && decorated.length > 1) decorated[1].hit = true;
    const hitAt = decorated.findIndex((row) => row.hit);
    const start = Math.max(0, (hitAt < 0 ? 0 : hitAt) - 1);
    return {
      filename: doc.filename,
      kind: "sheet",
      sheet: sheet ?? preferred.sheet,
      highlight,
      rows: decorated.slice(start, start + 8),
    };
  }

  return {
    filename: doc.filename,
    kind: "text",
    sheet,
    highlight,
    excerpt: excerptText(doc.markdown, highlight),
  };
}

export function resolveDealSource(deal: Deal, filename: string): string | null {
  const doc = deal.docs.find((item) => item.filename === filename);
  const candidates = [
    deal.sandbox ? path.join(deal.sandbox.workspace, filename) : "",
    path.join(dealRoot(deal.id), "workspace", filename),
    path.join(dealRoot(deal.id), filename),
    doc?.path ?? "",
  ];
  for (const candidate of candidates) {
    if (candidate && existsSync(candidate)) return path.resolve(candidate);
  }
  return resolveExisting(doc?.path ?? "", filename);
}

export function withEvidence(deal: Deal, flag: Flag): FlagView {
  const deck = flag.metric ? pick(deal.metrics, flag.metric, "deck") : undefined;
  const room = flag.metric
    ? deal.metrics.find((metric) => metric.name === flag.metric && metric.sourceKind !== "deck")
    : undefined;
  const deckValue = flag.deckValue ?? (deck ? formatMetric(deck) : undefined);
  const roomValue = flag.roomValue ?? (room ? formatMetric(room) : undefined);
  const filename = flag.sourceFile ?? room?.citation.filename;
  const sheet = flag.sourceSheet ?? room?.citation.sheet;
  const doc = filename ? deal.docs.find((item) => item.filename === filename) : undefined;

  let source: SourcePreview | undefined;
  if (flag.severity === "unsupported" || flag.severity === "missing") {
    source = {
      filename: filename ?? "data room",
      kind: "missing",
      highlight: deckValue ?? flag.quote,
    };
  } else if (doc) {
    source = previewDoc(doc, flag.metric, roomValue ?? room?.raw, sheet);
  }

  return {
    ...flag,
    deckValue,
    roomValue,
    sourceFile: filename,
    sourceSheet: sheet,
    sourceCitation: flag.sourceCitation || [filename, sheet].filter(Boolean).join(" · "),
    label: (flag.metric && METRIC_LABELS[flag.metric]) || flag.quote || "Finding",
    source,
  };
}

import { withEvidence } from "./evidence";
import { buildReconcile } from "./graph";
import type { Deal, DealRoomView } from "./types";

export function toRoomView(deal: Deal): DealRoomView {
  return {
    id: deal.id,
    name: deal.name,
    company: deal.company,
    status: deal.status,
    riskScore: deal.riskScore,
    sandbox: deal.sandbox,
    flags: deal.flags.map((flag) => withEvidence(deal, flag)),
    memo: deal.memo
      ? { verdict: deal.memo.verdict, bodyMarkdown: deal.memo.bodyMarkdown }
      : undefined,
    reconcile: deal.graph.rows?.length ? deal.graph.rows : buildReconcile(deal.metrics, deal.flags),
    files: deal.docs.map((doc) => ({ filename: doc.filename, kind: doc.kind })),
  };
}

import type { FlagView } from "@/lib/diligence/types";

const SEV = {
  contradiction: { label: "Doesn't match", className: "text-flag-red" },
  unsupported: { label: "Only on the deck", className: "text-flag-amber" },
  missing: { label: "Missing", className: "text-flag-gray" },
};

type Props = {
  dealId: string;
  flag: FlagView | null;
};

export function SourcePane({ dealId, flag }: Props) {
  if (!flag) {
    return (
      <aside className="min-h-0 overflow-y-auto border-l border-black/8 bg-memo px-5 py-6 text-ink">
        <p className="text-[15px] leading-7 text-ink/55">
          Click a mark on the slide to see the number it is pointing at, and the file it came from.
        </p>
      </aside>
    );
  }

  const meta = SEV[flag.severity];
  const source = flag.source;
  const href = flag.sourceFile
    ? `/api/deals/${dealId}/file?name=${encodeURIComponent(flag.sourceFile)}`
    : null;

  return (
    <aside className="min-h-0 overflow-y-auto border-l border-black/8 bg-memo px-5 py-6 text-ink">
      <p className={`font-mono text-[11px] ${meta.className}`}>{meta.label}</p>
      <h2 className="mt-1 font-serif text-[26px] leading-tight">{flag.label}</h2>

      <div className="mt-6 grid grid-cols-2 gap-4">
        <div>
          <p className="font-mono text-[11px] text-ink/40">On the slide</p>
          <p className="mt-1 text-[22px] leading-none">{flag.deckValue ?? flag.quote ?? "—"}</p>
          {flag.page ? (
            <p className="mt-2 font-mono text-[11px] text-ink/40">slide {flag.page}</p>
          ) : null}
        </div>
        <div>
          <p className="font-mono text-[11px] text-ink/40">In the room</p>
          <p className="mt-1 text-[22px] leading-none">{flag.roomValue ?? "—"}</p>
          {flag.sourceFile ? (
            href ? (
              <a
                href={href}
                className="mt-2 block font-mono text-[11px] text-copper underline-offset-2 hover:underline"
              >
                {flag.sourceFile}
                {flag.sourceSheet ? ` · ${flag.sourceSheet}` : ""}
              </a>
            ) : (
              <p className="mt-2 font-mono text-[11px] text-ink/40">
                {flag.sourceFile}
                {flag.sourceSheet ? ` · ${flag.sourceSheet}` : ""}
              </p>
            )
          ) : (
            <p className="mt-2 font-mono text-[11px] text-ink/40">no file</p>
          )}
        </div>
      </div>

      <p className="mt-5 text-[14px] leading-6 text-ink/70">{flag.comment}</p>

      {source?.kind === "sheet" && source.rows?.length ? (
        <div className="mt-6">
          <p className="font-mono text-[11px] text-ink/40">
            {source.filename}
            {source.sheet ? ` · ${source.sheet}` : ""}
          </p>
          <table className="source-table mt-2 w-full text-left">
            <tbody>
              {source.rows.map((row, index) => (
                <tr key={`${row.cells.join("|")}-${index}`} className={row.hit ? "source-hit" : ""}>
                  {row.cells.map((cell, cellIndex) => (
                    <td key={`${cell}-${cellIndex}`} className="py-1.5 pr-3 align-top">
                      {cell}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : null}

      {source?.kind === "text" && source.excerpt ? (
        <blockquote className="mt-6 border-l-2 border-copper/50 pl-3 text-[14px] leading-6 text-ink/75">
          {source.excerpt}
        </blockquote>
      ) : null}

      {source?.kind === "missing" ? (
        <p className="mt-6 text-[14px] leading-6 text-ink/55">
          Nothing in this room cites {flag.deckValue ?? "that number"}. The slide is on its own.
        </p>
      ) : null}

      {href ? (
        <a
          href={href}
          className="mt-6 inline-block font-mono text-[12px] text-copper underline-offset-2 hover:underline"
        >
          Open {flag.sourceFile}
        </a>
      ) : null}
    </aside>
  );
}

import { readFile } from "node:fs/promises";
import path from "node:path";
import { NextResponse } from "next/server";
import { resolveDealSource } from "@/lib/diligence/evidence";
import { assertInsideDeal } from "@/lib/diligence/sandbox";
import { loadDeal } from "@/lib/diligence/store";

const TYPES: Record<string, string> = {
  ".pdf": "application/pdf",
  ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  ".xls": "application/vnd.ms-excel",
  ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  ".pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
};

export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const name = new URL(request.url).searchParams.get("name");
  if (!name || name.includes("..") || name.includes("/") || name.includes("\\")) {
    return NextResponse.json({ error: "bad file name" }, { status: 400 });
  }
  const deal = await loadDeal(id);
  if (!deal) return NextResponse.json({ error: "not found" }, { status: 404 });
  const file = resolveDealSource(deal, name);
  if (!file) return NextResponse.json({ error: "file not in this room" }, { status: 404 });
  if (deal.sandbox) assertInsideDeal(id, file);
  const bytes = await readFile(file);
  const ext = path.extname(name).toLowerCase();
  return new NextResponse(Uint8Array.from(bytes), {
    headers: {
      "Content-Type": TYPES[ext] ?? "application/octet-stream",
      "Content-Disposition": `inline; filename="${name}"`,
      "Cache-Control": "no-store",
    },
  });
}

import type { FlagView } from "@/lib/diligence/types";

const SEV = {
  contradiction: { label: "Doesn't match", color: "text-flag-red", rule: "border-flag-red" },
  unsupported: { label: "Only on the deck", color: "text-flag-amber", rule: "border-flag-amber" },
  missing: { label: "Missing", color: "text-flag-gray", rule: "border-flag-gray" },
};

const ORDER = { contradiction: 0, unsupported: 1, missing: 2 };

type Props = {
  flags: FlagView[];
  activeId: string | null;
  onSelect: (id: string) => void;
};

export function FlagList({ flags, activeId, onSelect }: Props) {
  const sorted = flags.toSorted(
    (a, b) => ORDER[a.severity] - ORDER[b.severity] || (a.page ?? 99) - (b.page ?? 99),
  );

  return (
    <aside className="min-h-0 overflow-y-auto border-r border-white/10">
      <p className="px-5 pt-5 text-[13px] text-paper/45">On the slides</p>
      {sorted.length === 0 ? (
        <p className="px-5 py-6 text-[14px] leading-6 text-paper/40">No flags on this deck yet.</p>
      ) : (
        <ul>
          {sorted.map((flag) => {
            const meta = SEV[flag.severity];
            const on = activeId === flag.id;
            return (
              <li key={flag.id} className="flag-row">
                <button
                  type="button"
                  onClick={() => onSelect(flag.id)}
                  className={`w-full border-l-2 px-5 py-4 text-left ${meta.rule} ${on ? "bg-white/6" : ""}`}
                >
                  <div className="flex items-baseline justify-between gap-3">
                    <span className={`font-mono text-[11px] ${meta.color}`}>{meta.label}</span>
                    <span className="font-mono text-[11px] text-paper/35">
                      {flag.page ? `slide ${flag.page}` : "room"}
                    </span>
                  </div>
                  <p className="mt-1.5 font-serif text-[18px] leading-6 text-paper">
                    {flag.deckValue ?? flag.quote || flag.label}
                    {flag.roomValue ? <span className="text-paper/45"> → {flag.roomValue}</span> : null}
                  </p>
                  <p className="mt-1 font-mono text-[11px] text-copper">
                    {flag.sourceFile
                      ? `${flag.sourceFile}${flag.sourceSheet ? ` · ${flag.sourceSheet}` : ""}`
                      : "no source in the room"}
                  </p>
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </aside>
  );
}

