"use client";

import type { DealRoomView, FlagView } from "@/lib/diligence/types";
import { AskPanel } from "./AskPanel";
import { MemoPanel } from "./MemoPanel";
import { ReconciliationMap } from "./ReconciliationMap";
import { SourcePane } from "./SourcePane";

const PANES = [
  { id: "source", label: "Source" },
  { id: "compare", label: "Compare" },
  { id: "memo", label: "Memo" },
  { id: "ask", label: "Ask" },
] as const;

export type SidePane = (typeof PANES)[number]["id"];

type Props = {
  deal: DealRoomView;
  flag: FlagView | null;
  pane: SidePane;
  onPane: (pane: SidePane) => void;
  onOpenFlag: (id: string) => void;
};

export function SideDesk({ deal, flag, pane, onPane, onOpenFlag }: Props) {
  return (
    <aside
      id="side-desk"
      className="flex min-h-0 min-w-0 flex-col border-l border-black/10 bg-memo text-ink"
    >
      <nav className="flex shrink-0 border-b border-black/10 px-2">
        {PANES.map((item) => (
          <button
            key={item.id}
            type="button"
            onClick={() => onPane(item.id)}
            className={`px-3 py-3 text-[13px] ${pane === item.id ? "text-ink" : "text-ink/35"}`}
          >
            {item.label}
          </button>
        ))}
      </nav>
      <div className="min-h-0 flex-1 overflow-y-auto">
        {pane === "source" ? (
          <SourcePane dealId={deal.id} flag={flag} />
        ) : pane === "compare" ? (
          <ReconciliationMap
            rows={deal.reconcile}
            activeId={flag?.id ?? null}
            onOpenFlag={onOpenFlag}
            compact
          />
        ) : pane === "memo" ? (
          <div className="px-6 py-6">
            <MemoPanel verdict={deal.memo?.verdict} bodyMarkdown={deal.memo?.bodyMarkdown} />
          </div>
        ) : (
          <AskPanel dealId={deal.id} compact />
        )}
      </div>
    </aside>
  );
}

import type { FlagView } from "@/lib/diligence/types";

const SEV = {
  contradiction: { label: "Doesn't match", className: "text-flag-red" },
  unsupported: { label: "Only on the deck", className: "text-flag-amber" },
  missing: { label: "Missing from the room", className: "text-flag-gray" },
};

type Props = {
  dealId: string;
  flag: FlagView | null;
};

export function SourcePane({ dealId, flag }: Props) {
  if (!flag) {
    return (
      <div className="px-6 py-7">
        <p className="font-serif text-[22px] leading-8 text-ink/70">
          Click a mark on the slide. This pane opens the number and the file behind it.
        </p>
      </div>
    );
  }

  const meta = SEV[flag.severity];
  const source = flag.source;
  const href = flag.sourceFile
    ? `/api/deals/${dealId}/file?name=${encodeURIComponent(flag.sourceFile)}`
    : null;

  return (
    <div className="px-6 py-6">
      <p className={`font-mono text-[11px] ${meta.className}`}>{meta.label}</p>
      <h2 className="mt-1 font-serif text-[26px] leading-tight">{flag.label}</h2>
      <p className="mt-3 text-[14px] leading-6 text-ink/65">{flag.comment}</p>

      <div className="mt-6 flex items-end gap-5">
        <div className="min-w-0 flex-1">
          <p className="font-mono text-[11px] text-ink/40">Slide{flag.page ? ` ${flag.page}` : ""}</p>
          <p className="mt-1 font-serif text-[32px] leading-none tracking-tight">
            {flag.deckValue ?? flag.quote ?? "—"}
          </p>
        </div>
        <p className="mb-1 font-mono text-[12px] text-ink/25">→</p>
        <div className="min-w-0 flex-1">
          <p className="font-mono text-[11px] text-ink/40">This file</p>
          <p className="mt-1 font-serif text-[32px] leading-none tracking-tight">
            {flag.roomValue ?? "—"}
          </p>
        </div>
      </div>

      {source?.kind === "sheet" && source.rows?.length ? (
        <div className="source-file mt-7">
          <header>
            {href ? (
              <a href={href} className="text-ink underline-offset-2 hover:underline">
                {source.filename}
              </a>
            ) : (
              <span>{source.filename}</span>
            )}
            {source.sheet ? <span className="sheet">{source.sheet}</span> : null}
          </header>
          <table>
            <tbody>
              {source.rows.map((row, index) => (
                <tr key={`${row.cells.join("|")}-${index}`} className={row.hit ? "source-hit" : ""}>
                  {row.cells.map((cell, cellIndex) => (
                    <td key={`${cell}-${cellIndex}`}>{cell}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : null}

      {source?.kind === "text" && source.excerpt ? (
        <div className="source-file mt-7">
          <header>
            {href ? (
              <a href={href} className="text-ink underline-offset-2 hover:underline">
                {source.filename}
              </a>
            ) : (
              <span>{source.filename}</span>
            )}
          </header>
          <p className="excerpt">{source.excerpt}</p>
        </div>
      ) : null}

      {source?.kind === "missing" ? (
        <div className="source-file mt-7">
          <header>
            <span>Data room</span>
          </header>
          <p className="excerpt">
