import { chromium } from "playwright";

const BASE = process.env.BASE_URL ?? "http://127.0.0.1:3000";

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
page.on("pageerror", (err) => console.error("PAGEERROR", err.message));
page.on("console", (msg) => {
  if (msg.type() === "error") console.error("CONSOLE", msg.text());
});

await page.goto(BASE, { waitUntil: "networkidle" });
const title = await page.locator("h1").first().textContent();
if (!title?.includes("Open a deal")) throw new Error(`home title: ${title}`);

const named = page.locator("a", { hasText: "Northstar Robotics" }).first();
if (await named.count()) {
  await named.click();
} else {
  await page.locator("section a").first().click();
}
await page.waitForURL(/\/deals\//);

await page.waitForTimeout(2500);
const canvases = await page.locator("main canvas").count();
const iframe = await page.locator("main iframe").count();
const highlights = await page.locator("main .slide-hl").count();
const fail = await page.getByText("Could not render the deck").count();
if (fail) throw new Error("deck hard-failed");
if (canvases < 1 && iframe < 1) throw new Error("no canvas and no iframe");
if (highlights < 4) throw new Error(`expected on-slide highlights, got ${highlights}`);

const flags = await page.locator("aside").first().locator("button").count();
if (flags < 4) throw new Error(`expected flags, got ${flags}`);

const desk = page.locator("#side-desk");
if (!(await desk.getByText("northstar-financial-model").count())) {
  throw new Error(`source file missing: ${await desk.textContent()}`);
}
if (!(await desk.getByText("$2.8M").count())) {
  throw new Error(`source number missing: ${await desk.textContent()}`);
}

await page.locator("aside").first().locator("button").nth(2).click();
await page.waitForTimeout(200);
if (!(await desk.getByText(/27 people|headcount/i).count())) {
  throw new Error(`flag click did not update source: ${await desk.textContent()}`);
}

await page.locator("main .slide-hl").first().click();
await page.waitForTimeout(200);
if (!(await desk.getByText("northstar-financial-model").count())) {
  throw new Error(`highlight click did not open source: ${await desk.textContent()}`);
}

await desk.getByRole("button", { name: "Compare" }).click();
await page.waitForTimeout(200);
if (!(await desk.getByText("What the deck says vs the room").count())) {
  throw new Error("compare view missing");
}

await desk.getByRole("button", { name: "Ask" }).click();
await page.locator("textarea").waitFor();
await desk.getByRole("button", { name: "Ask" }).last().click();
await page.waitForTimeout(1500);

await page.screenshot({ path: "/tmp/night-desk-deal.png", fullPage: true });
console.log(
  JSON.stringify({
    canvases,
    highlights,
    iframe,
    flags,
    url: page.url(),
    ok: true,
  }),
);
await browser.close();

