input.contents:
import { randomUUID } from "node:crypto";
import { existsSync } from "node:fs";
import { cp, mkdir } from "node:fs/promises";
import path from "node:path";
import { annotateDeck } from "./annotate";
import { riskScore, runChecklist } from "./checklist";
import { resolveExisting } from "./files";
import { buildGraph } from "./graph";
import { ingestFolder } from "./ingest";
import { draftMemo } from "./memo";
import { extractMetrics } from "./metrics";
import { dirs } from "./paths";
import { copyInto, dealRoot, isolateDeal } from "./sandbox";
import { saveDeal } from "./store";
import type { Deal, DealEvent, DealSandbox } from "./types";

function slug(name: string) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40);
}

function guessCompany(folder: string, files: string[]): string {
  if (files.some((f) => /northstar/i.test(f))) return "Northstar Robotics";
  const fromName = path.basename(folder).replace(/[-_]/g, " ").replace(/\d+/g, "").trim();
  if (fromName && fromName.toLowerCase() !== "northstar") {
    return fromName.replace(/\b\w/g, (c) => c.toUpperCase()) || "Untitled deal";
  }
  return "Untitled deal";
}

function pusher(events: DealEvent[]) {
  return (stage: DealEvent["stage"], message: string) => {
    events.push({ at: new Date().toISOString(), stage, message });
  };
}

async function finishDeal(deal: Deal, push: ReturnType<typeof pusher>): Promise<Deal> {
  if (!deal.sandbox) throw new Error("Deal has no workspace");
  deal.docs = await ingestFolder(deal.sandbox.workspace);
  deal.company = deal.company || guessCompany(deal.sourcePath, deal.docs.map((d) => d.filename));
  deal.deckFilename = deal.docs.find((d) => d.kind === "deck")?.filename;
  deal.status = "graphing";
  deal.updatedAt = new Date().toISOString();
  await saveDeal(deal);

  push("graph", "Extracting numbers and linking sources");
  deal.metrics = await extractMetrics(deal.docs);
  deal.status = "diligence";
  await saveDeal(deal);

  push("diligence", "Cross-checking the deck against the financials");
  deal.flags = runChecklist(deal, deal.metrics);
  deal.riskScore = riskScore(deal.flags);
  deal.graph = buildGraph(deal.company, deal.metrics, deal.flags);

  deal.status = "annotating";
  push("annotate", "Marking the deck and drafting the memo");
  deal.memo = await draftMemo(deal);
  await annotateDeck(deal, path.join(dirs().outbox, deal.id));

  deal.status = "ready";
  deal.error = undefined;
  deal.updatedAt = new Date().toISOString();
  push("ready", `${deal.flags.length} findings · risk ${deal.riskScore}`);
  await saveDeal(deal);
  return deal;
}

export async function ensureWorkspace(deal: Deal): Promise<DealSandbox> {
  if (deal.sandbox?.workspace && existsSync(deal.sandbox.workspace)) return deal.sandbox;
  const workspace = path.join(dealRoot(deal.id), "workspace");
  await mkdir(workspace, { recursive: true });
  for (const doc of deal.docs) {
    const src = resolveExisting(doc.path, doc.filename);
    if (!src) continue;
    await cp(src, path.join(workspace, path.basename(doc.filename)));
  }
  deal.sandbox = { kind: "local", root: dealRoot(deal.id), workspace };
  return deal.sandbox;
}

export async function runDeal(sourcePath: string, name?: string): Promise<Deal> {
  const now = new Date().toISOString();
  sourcePath = path.resolve(sourcePath);
  const id = `${slug(name || path.basename(sourcePath))}-${randomUUID().slice(0, 8)}`;
  const events: DealEvent[] = [];
  const push = pusher(events);

  const deal: Deal = {
    id,
    name: name || path.basename(sourcePath),
    company: "",
    status: "ingesting",
    createdAt: now,
    updatedAt: now,
    sourcePath,
    docs: [],
    metrics: [],
    flags: [],
    graph: { nodes: [], edges: [], rows: [] },
    events,
  };

  try {
    push("ingest", "Sealing a room and reading the files");
    deal.sandbox = await isolateDeal(id, sourcePath);
    return await finishDeal(deal, push);
  } catch (error) {
    deal.status = "error";
    deal.error = (error as Error).message;
    deal.updatedAt = new Date().toISOString();
    push("error", deal.error);
    await saveDeal(deal);
    throw error;
  }
}

export async function addFilesToDeal(deal: Deal, incomingPath: string): Promise<Deal> {
  const push = pusher(deal.events);
  try {
    deal.status = "ingesting";
    push("ingest", "Adding files to the room");
    deal.sandbox = await ensureWorkspace(deal);
    await copyInto(incomingPath, deal.sandbox.workspace);
    return await finishDeal(deal, push);
  } catch (error) {
    deal.status = "error";
    deal.error = (error as Error).message;
    deal.updatedAt = new Date().toISOString();
    push("error", deal.error);
    await saveDeal(deal);
    throw error;
  }
}

import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { NextResponse } from "next/server";
import { addFilesToDeal } from "@/lib/diligence/pipeline";
import { dirs } from "@/lib/diligence/paths";
import { loadDeal } from "@/lib/diligence/store";

function safeName(name: string) {
  return path.basename(name).replace(/[^\w.\- ()]+/g, "-");
}

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const deal = await loadDeal(id);
  if (!deal) return NextResponse.json({ error: "Deal not found" }, { status: 404 });

  const form = await request.formData();
  const files = form.getAll("files").filter((item): item is File => item instanceof File && item.size > 0);
  if (!files.length) return NextResponse.json({ error: "Choose at least one file" }, { status: 400 });

  const folder = path.join(dirs().inbox, `add-${id}-${Date.now()}`);
  await mkdir(folder, { recursive: true });
  for (const file of files) {
    const name = safeName(file.name);
    if (!name || name === "." || name === "..") continue;
    await writeFile(path.join(folder, name), Buffer.from(await file.arrayBuffer()));
  }

  const next = await addFilesToDeal(deal, folder);
  return NextResponse.json({ id: next.id, status: next.status, files: next.docs.map((doc) => doc.filename) });
}

"use client";

import { useState } from "react";

type Props = {
  id: string;
  label: string;
  hint: string;
  files: File[];
  onFiles: (files: File[]) => void;
  disabled?: boolean;
};

function merge(current: File[], incoming: FileList | File[]) {
  const next = [...current];
  for (const file of Array.from(incoming)) {
    if (!next.some((item) => item.name === file.name && item.size === file.size)) next.push(file);
  }
  return next;
}

export function FileDrop({ id, label, hint, files, onFiles, disabled = false }: Props) {
  const [over, setOver] = useState(false);

  return (
    <div>
      <label
        htmlFor={id}
        className={`block cursor-pointer border border-dashed px-4 py-5 ${
          over ? "border-copper bg-white/4" : "border-white/25"
        } ${disabled ? "opacity-50" : ""}`}
        onDragOver={(event) => {
          event.preventDefault();
          if (!disabled) setOver(true);
        }}
        onDragLeave={() => setOver(false)}
        onDrop={(event) => {
          event.preventDefault();
          setOver(false);
          if (!disabled) onFiles(merge(files, event.dataTransfer.files));
        }}
      >
        <span className="block text-[16px] text-paper">{label}</span>
        <span className="mt-1 block text-[14px] leading-6 text-paper/70">{hint}</span>
        <input
          id={id}
          type="file"
          multiple
          disabled={disabled}
          accept=".pdf,.pptx,.ppt,.xlsx,.xls,.docx,.doc,.csv"
          className="mt-4 block w-full text-[14px] text-paper file:mr-3 file:border-0 file:bg-paper file:px-3 file:py-1.5 file:text-ink"
          onChange={(event) => {
            if (event.target.files) onFiles(merge(files, event.target.files));
            event.target.value = "";
          }}
        />
      </label>
      {files.length > 0 ? (
        <ul className="mt-3" aria-label="Files ready to add">
          {files.map((file) => (
            <li key={`${file.name}-${file.size}`} className="flex items-center justify-between gap-4 py-1.5 text-[14px]">
              <span>{file.name}</span>
              <button
                type="button"
                disabled={disabled}
                onClick={() => onFiles(files.filter((item) => item !== file))}
                className="text-paper/70 underline-offset-2 hover:text-paper hover:underline"
              >
