"use client";

import { useState } from "react";
import type { SourcePreview } from "@/lib/diligence/types";

type Props = {
  preview: SourcePreview;
  href?: string;
  openHref?: string;
};

export function FilePreview({ preview, href, openHref }: Props) {
  const sheets = preview.sheets?.length
    ? preview.sheets
    : preview.rows?.length
      ? [{ name: preview.sheet ?? "Sheet", rows: preview.rows }]
      : [];
  const [sheetName, setSheetName] = useState(sheets[0]?.name ?? "");
  const active = sheets.find((sheet) => sheet.name === sheetName) ?? sheets[0];
  const header = active?.rows[0];
  const body = active?.rows.slice(1) ?? [];
  const open = openHref ?? href;

  return (
    <div className="source-file">
      <div className="source-toolbar">
        <p className="source-name">{preview.filename}</p>
        {open ? (
          <a href={open} target="_blank" rel="noreferrer" className="source-open">
            Open in new tab
          </a>
        ) : null}
      </div>

      {sheets.length > 1 ? (
        <div className="sheet-tabs" role="tablist" aria-label="Sheets">
          {sheets.map((sheet) => (
            <button
              key={sheet.name}
              type="button"
              role="tab"
              aria-selected={sheet.name === active?.name}
              className={sheet.name === active?.name ? "is-on" : ""}
              onClick={() => setSheetName(sheet.name)}
            >
              {sheet.name}
            </button>
          ))}
        </div>
      ) : null}

      {active?.rows.length ? (
        <div className="source-scroll">
          <table>
            {header ? (
              <thead>
                <tr>
                  {header.cells.map((cell, index) => (
                    <th key={`${cell}-${index}`}>{cell}</th>
                  ))}
                </tr>
              </thead>
            ) : null}
            <tbody>
              {body.map((row, index) => (
                <tr key={`${row.cells.join("|")}-${index}`} className={row.hit ? "source-hit" : ""}>
                  {row.cells.map((cell, cellIndex) => (
                    <td key={`${cell}-${cellIndex}`}>{cell}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : null}

      {preview.kind === "text" || preview.paragraphs?.length ? (
        <div className="source-doc">
          {(preview.paragraphs?.length ? preview.paragraphs : preview.excerpt ? [preview.excerpt] : []).map(
            (paragraph) => (
              <p key={paragraph.slice(0, 48)}>{paragraph}</p>
            ),
          )}
        </div>
      ) : null}
    </div>
  );
}

