import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { NextResponse } from "next/server";
import { dirs } from "@/lib/diligence/paths";
import { runDeal } from "@/lib/diligence/pipeline";
import { parseRoles } from "@/lib/diligence/roles";

export const maxDuration = 300;

export async function POST(request: Request) {
  try {
    const form = await request.formData();
    const files = form.getAll("files").filter((f): f is File => f instanceof File && f.size > 0);
    if (!files.length) return NextResponse.json({ error: "Choose at least one file" }, { status: 400 });
    const name = String(form.get("name") || files[0].name.replace(/\.[^.]+$/, "") || "deal");
    const roles = parseRoles(form.get("roles"));
    const folder = path.join(dirs().staging, `upload-${name.replace(/[^\w.-]+/g, "-")}-${Date.now()}`);
    await mkdir(folder, { recursive: true });
    for (const file of files) {
      const safe = path.basename(file.name).replace(/[^\w.\- ()]+/g, "-");
      if (!safe || safe === "." || safe === "..") continue;
      await writeFile(path.join(folder, safe), Buffer.from(await file.arrayBuffer()));
    }
    const deal = await runDeal(folder, name, roles);
    return NextResponse.json({ id: deal.id, status: deal.status, decks: deal.deckFilenames ?? [] });
  } catch (error) {
    return NextResponse.json(
      { error: (error as Error).message || "Could not start this deal" },
      { status: 500 },
    );
  }
}

import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { NextResponse } from "next/server";
import { addFilesToDeal } from "@/lib/diligence/pipeline";
import { dirs } from "@/lib/diligence/paths";
import { parseRoles } from "@/lib/diligence/roles";
import { loadDeal } from "@/lib/diligence/store";

export const maxDuration = 300;

function safeName(name: string) {
  return path.basename(name).replace(/[^\w.\- ()]+/g, "-");
}

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const deal = await loadDeal(id);
    if (!deal) return NextResponse.json({ error: "Deal not found" }, { status: 404 });

    const form = await request.formData();
    const files = form.getAll("files").filter((item): item is File => item instanceof File && item.size > 0);
    if (!files.length) return NextResponse.json({ error: "Choose at least one file" }, { status: 400 });
    const roles = parseRoles(form.get("roles"));

    const folder = path.join(dirs().staging, `add-${id}-${Date.now()}`);
    await mkdir(folder, { recursive: true });
    let saved = 0;
    for (const file of files) {
      const name = safeName(file.name);
      if (!name || name === "." || name === "..") continue;
      await writeFile(path.join(folder, name), Buffer.from(await file.arrayBuffer()));
      saved += 1;
    }
    if (!saved) return NextResponse.json({ error: "Those file names were not usable" }, { status: 400 });

    const next = await addFilesToDeal(deal, folder, roles);
    return NextResponse.json({
      id: next.id,
      status: next.status,
      files: next.docs.map((doc) => doc.filename),
      decks: next.deckFilenames ?? [],
    });
  } catch (error) {
    return NextResponse.json(
      { error: (error as Error).message || "Could not add those files" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { setFileRole } from "@/lib/diligence/pipeline";
import { loadDeal } from "@/lib/diligence/store";
import type { FileRole } from "@/lib/diligence/types";

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const deal = await loadDeal(id);
    if (!deal) return NextResponse.json({ error: "Deal not found" }, { status: 404 });
    const body = (await request.json()) as { filename?: string; role?: FileRole };
    if (!body.filename || (body.role !== "deck" && body.role !== "room")) {
      return NextResponse.json({ error: "Choose a file and whether it is a deck or data room" }, { status: 400 });
    }
    const next = await setFileRole(deal, body.filename, body.role);
    return NextResponse.json({
      id: next.id,
      filename: body.filename,
      role: body.role,
      decks: next.deckFilenames ?? [],
    });
  } catch (error) {
    return NextResponse.json(
      { error: (error as Error).message || "Could not move that file" },
      { status: 500 },
    );
  }
}

import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { NextResponse } from "next/server";
import { resolveExisting } from "@/lib/diligence/files";
import { dirs } from "@/lib/diligence/paths";
import { deckDocs } from "@/lib/diligence/roles";
import { assertInsideDeal } from "@/lib/diligence/sandbox";
import { loadDeal } from "@/lib/diligence/store";
import { resolveDealSource } from "@/lib/diligence/evidence";

export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const deal = await loadDeal(id);
  if (!deal) return NextResponse.json({ error: "Deal not found" }, { status: 404 });
  const name = new URL(request.url).searchParams.get("name") ?? undefined;
  const decks = deckDocs(deal.docs);
  const chosen =
    decks.find((doc) => doc.filename === name) ??
    decks.find((doc) => doc.filename === deal.deckFilename) ??
    decks[0];
  const stored = path.join(dirs().data, id, "deck.pdf");
  const fromRoom = chosen ? resolveDealSource(deal, chosen.filename) : null;
  const fallback = chosen ? resolveExisting(chosen.path, chosen.filename) : null;
  const file =
    (name && fromRoom) ||
    fromRoom ||
    (existsSync(stored) && !name ? stored : null) ||
    fallback;
  if (!file) return NextResponse.json({ error: "no deck" }, { status: 404 });
  if (deal.sandbox) assertInsideDeal(id, file);
  const bytes = await readFile(file);
  return new NextResponse(Uint8Array.from(bytes), {
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": `inline; filename="${chosen?.filename ?? "deck.pdf"}"`,
      "Cache-Control": "no-store",
    },
  });
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { type FormEvent, useState, useTransition } from "react";
import type { DealFile, DealLobbyView, FileRole } from "@/lib/diligence/types";
import { riskTone } from "@/lib/format";
import { readJson } from "@/lib/http";
import { FileDrop, roleMap, type StagedFile } from "./FileDrop";
import { FileGraph } from "./FileGraph";
import { FilePreview } from "./FilePreview";
import { ReconciliationMap } from "./ReconciliationMap";

const KIND: Record<DealFile["kind"], string> = {
  deck: "Pitch deck",
  financials: "Financials",
  cap_table: "Cap table",
  metrics: "Operating metrics",
  other: "File",
};

type Props = {
  deal: DealLobbyView;
};

export function DealLobby({ deal }: Props) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [incoming, setIncoming] = useState<StagedFile[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<string | null>(
    deal.room[0]?.filename ?? deal.decks[0]?.filename ?? null,
  );
  const file =
    deal.room.find((item) => item.filename === selected) ??
    deal.decks.find((item) => item.filename === selected);
  const preview = selected ? deal.previews[selected] : undefined;

  function addToRoom(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!incoming.length) {
      setError("Choose the files you want to add.");
      return;
    }
    setError(null);
    setMessage("Adding files and re-reading the room…");
    const form = new FormData();
    for (const item of incoming) form.append("files", item.file);
    form.append("roles", JSON.stringify(roleMap(incoming)));
    startTransition(async () => {
      const res = await fetch(`/api/deals/${deal.id}/files`, { method: "POST", body: form });
      const data = await readJson(res);
      if (!res.ok) {
        setError(typeof data.error === "string" ? data.error : "Could not add those files");
        setMessage(null);
        return;
      }
      setIncoming([]);
      const files = Array.isArray(data.files) ? data.files : [];
      setMessage(`Added. This room now has ${files.length || "updated"} files.`);
      router.refresh();
    });
  }

  function moveFile(filename: string, role: FileRole) {
    setError(null);
    setMessage(role === "deck" ? `Moving ${filename} to decks…` : `Moving ${filename} to the data room…`);
    startTransition(async () => {
      const res = await fetch(`/api/deals/${deal.id}/role`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ filename, role }),
      });
      const data = await readJson(res);
      if (!res.ok) {
        setError(typeof data.error === "string" ? data.error : "Could not move that file");
        setMessage(null);
        return;
      }
      setMessage(role === "deck" ? `${filename} is now a deck.` : `${filename} is in the data room.`);
      router.refresh();
    });
  }

  return (
    <div className="min-h-screen bg-desk text-paper">
