import { NextResponse } from "next/server";
import { resolveDealSource } from "@/lib/diligence/evidence";
import { assertInsideDeal } from "@/lib/diligence/sandbox";
import { loadDeal } from "@/lib/diligence/store";
import { readWorkbookGrid } from "@/lib/diligence/workbook";

export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const name = new URL(request.url).searchParams.get("name");
    if (!name || name.includes("..") || name.includes("/") || name.includes("\\")) {
      return NextResponse.json({ error: "bad file name" }, { status: 400 });
    }
    if (!/\.xlsx?$/i.test(name)) {
      return NextResponse.json({ error: "not a workbook" }, { status: 400 });
    }
    const deal = await loadDeal(id);
    if (!deal) return NextResponse.json({ error: "not found" }, { status: 404 });
    const file = resolveDealSource(deal, name);
    if (!file) return NextResponse.json({ error: "file not in this room" }, { status: 404 });
    if (deal.sandbox) assertInsideDeal(id, file);
    const grid = await readWorkbookGrid(file, name);
    return NextResponse.json(grid, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return NextResponse.json(
      { error: (error as Error).message || "Could not open that workbook" },
      { status: 500 },
    );
  }
}

"use client";

import { useEffect, useState } from "react";
import type { WorkbookGrid, WorkbookSheet } from "@/lib/diligence/types";

type Props = {
  href: string;
  highlight?: string;
  compact?: boolean;
};

function colLetter(index: number) {
  let n = index + 1;
  let out = "";
  while (n > 0) {
    const rem = (n - 1) % 26;
    out = String.fromCharCode(65 + rem) + out;
    n = Math.floor((n - 1) / 26);
  }
  return out;
}

export function WorkbookViewer({ href, highlight, compact = false }: Props) {
  const [grid, setGrid] = useState<WorkbookGrid | null>(null);
  const [sheetName, setSheetName] = useState("");
  const [error, setError] = useState<string | null>(null);
  const workbookHref = href.replace("/file?", "/workbook?");

  useEffect(() => {
    let dead = false;
    setGrid(null);
    setError(null);
    void fetch(workbookHref)
      .then(async (res) => {
        const data = (await res.json()) as WorkbookGrid & { error?: string };
        if (!res.ok) throw new Error(data.error || "Could not open workbook");
        if (!dead) {
          setGrid(data);
          setSheetName(data.sheets[0]?.name ?? "");
        }
      })
      .catch((err: Error) => {
        if (!dead) setError(err.message);
      });
    return () => {
      dead = true;
    };
  }, [workbookHref]);

  const sheet: WorkbookSheet | undefined =
    grid?.sheets.find((item) => item.name === sheetName) ?? grid?.sheets[0];
  const needle = highlight?.toLowerCase() ?? "";

  if (error) return <p className="xl-error">{error}</p>;
  if (!sheet) return <p className="xl-error">Opening workbook…</p>;

  return (
    <div className={`xl-app ${compact ? "is-compact" : ""}`}>
      <div className="xl-formula" aria-hidden="true">
        <span>fx</span>
        <span>{sheet.name}</span>
      </div>
      <div className="xl-scroll">
        <table>
          <colgroup>
            <col style={{ width: 36 }} />
            {sheet.columns.map((column, index) => (
              <col key={colLetter(index)} style={{ width: Math.max(64, column.width) }} />
            ))}
          </colgroup>
          <thead>
            <tr>
              <th className="xl-corner" />
              {sheet.columns.map((_, index) => (
                <th key={colLetter(index)} className="xl-colh">
                  {colLetter(index)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sheet.rows.map((row, rowIndex) => {
              const hit =
                Boolean(needle) &&
                row.cells.some((cell) => cell.text.toLowerCase().includes(needle));
              return (
                <tr key={`r${rowIndex + 1}`} className={hit ? "xl-hit" : undefined}>
                  <th className="xl-rowh">{rowIndex + 1}</th>
                  {row.cells.map((cell, cellIndex) => (
                    <td
                      key={`${rowIndex}-${cellIndex}`}
                      style={{
                        textAlign: cell.align,
                        fontWeight: cell.bold ? 600 : undefined,
                        background: cell.fill,
                      }}
                    >
                      {cell.text}
                    </td>
                  ))}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="xl-tabs" role="tablist" aria-label="Sheets">
        {grid.sheets.map((item) => (
          <button
            key={item.name}
            type="button"
            role="tab"
            aria-selected={item.name === sheet.name}
            className={item.name === sheet.name ? "is-on" : ""}
            onClick={() => setSheetName(item.name)}
          >
            {item.name}
          </button>
        ))}
      </div>
    </div>
  );
}

