"use client";

import type { SourcePreview } from "@/lib/diligence/types";
import { NativePdf } from "./NativePdf";
import { WorkbookViewer } from "./WorkbookViewer";

type Props = {
  preview: SourcePreview;
  href?: string;
  openHref?: string;
  compact?: boolean;
  fill?: boolean;
};

export function FilePreview({ preview, href, openHref, compact = false, fill = false }: Props) {
  const open = openHref ?? href;
  const isPdf = /\.pdf$/i.test(preview.filename);
  const isXlsx = /\.xlsx?$/i.test(preview.filename);
  const native = Boolean(href) && (isPdf || isXlsx);

  return (
    <div className={`source-file ${fill ? "is-fill" : ""}`}>
      <div className="source-toolbar">
        <p className="source-name">
          {preview.filename}
          {preview.sheet ? <span className="source-sheet"> · {preview.sheet}</span> : null}
        </p>
        <div className="source-actions">
          {open ? (
            <a href={open} target="_blank" rel="noreferrer" className="source-open">
              Open in new tab
            </a>
          ) : null}
          {href ? (
            <a href={href} className="source-download">
              Download
            </a>
          ) : null}
        </div>
      </div>

      <div className="preview-body">
        {isPdf && href ? <NativePdf src={href} title={preview.filename} /> : null}
        {isXlsx && href ? (
          <WorkbookViewer href={href} highlight={preview.highlight} compact={compact} />
        ) : null}
        {!native && (preview.kind === "text" || preview.paragraphs?.length) ? (
          <div className="source-doc">
            {(preview.paragraphs?.length ? preview.paragraphs : preview.excerpt ? [preview.excerpt] : []).map(
              (paragraph) => (
                <p key={paragraph.slice(0, 48)}>{paragraph}</p>
              ),
            )}
          </div>
        ) : null}
      </div>
    </div>
  );
}

