const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto(BASE, { waitUntil: "networkidle" });
const named = page.locator("a", { hasText: "Northstar Robotics" }).first();
if (await named.count()) await named.click();
else await page.locator("section a").first().click();
await page.waitForURL(/\/deals\/[^/]+$/);

const empty = await page.evaluate(() => {
  const split = document.querySelector(".lobby-split");
  const files = document.querySelector(".lobby-files");
  const preview = document.querySelector(".lobby-preview");
  const blotter = document.querySelector(".lobby-empty");
  const sr = split?.getBoundingClientRect();
  const fr = files?.getBoundingClientRect();
  const pr = preview?.getBoundingClientRect();
  const er = blotter?.getBoundingClientRect();
  return {
    docScroll: document.documentElement.scrollHeight,
    view: window.innerHeight,
    splitH: Math.round(sr?.height ?? 0),
    filesH: Math.round(fr?.height ?? 0),
    previewH: Math.round(pr?.height ?? 0),
    previewW: Math.round(pr?.width ?? 0),
    emptyH: Math.round(er?.height ?? 0),
    filesLeft: Math.round(fr?.left ?? -1),
    previewLeft: Math.round(pr?.left ?? -1),
