import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdir, readFile, stat, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { promisify } from "node:util";

const exec = promisify(execFile);

function bin(name: string): string | null {
  for (const dir of ["/opt/homebrew/bin", "/usr/local/bin", "/usr/bin"]) {
    const full = path.join(dir, name);
    if (existsSync(full)) return full;
  }
  return null;
}

export function pagesNeedOcr(pages: Record<number, string>): boolean {
  const values = Object.values(pages);
  if (!values.length) return true;
  return values.every((text) => text.replace(/\s+/g, "").length < 8);
}

export async function ocrPdfPages(filePath: string): Promise<Record<number, string>> {
  const magick = bin("magick");
  const tesseract = bin("tesseract");
  if (!magick || !tesseract) return {};

  const info = await stat(filePath);
  const cache = `${filePath}.ocr.json`;
  if (existsSync(cache)) {
    try {
      const saved = JSON.parse(await readFile(cache, "utf8")) as {
        mtime: number;
        pages: Record<number, string>;
      };
      if (saved.mtime === info.mtimeMs && saved.pages && Object.keys(saved.pages).length) {
        return saved.pages;
      }
    } catch {
      // redo
    }
  }

  const work = path.join(os.tmpdir(), "night-desk-ocr", path.basename(filePath, ".pdf"));
  await mkdir(work, { recursive: true });
  const pages: Record<number, string> = {};
  for (let page = 1; page <= 24; page++) {
    const png = path.join(work, `p-${page}.png`);
    try {
      await exec(magick, [
        "-density",
        "140",
        `${filePath}[${page - 1}]`,
        "-alpha",
        "off",
        "-depth",
        "8",
        "-colorspace",
        "sRGB",
        png,
      ]);
    } catch {
      break;
    }
    if (!existsSync(png)) break;
    try {
      const { stdout } = await exec(tesseract, [png, "stdout", "-l", "eng", "--psm", "6"]);
      pages[page] = stdout.replace(/\s+/g, " ").trim();
    } catch {
      pages[page] = "";
    }
  }

  if (Object.values(pages).some((text) => text.length > 8)) {
    await writeFile(cache, JSON.stringify({ mtime: info.mtimeMs, pages }));
  }
  return pages;
}

