function firstNumber(text: string): number | null {
  const match = text.replace(/,/g, "").match(/(\d+(?:\.\d+)?)\s*([bnk])?/i);
  if (!match) return null;
  let n = Number(match[1]);
  if (!Number.isFinite(n)) return null;
  if (/^b$/i.test(match[2] ?? "")) n *= 1_000_000_000;
