function flagHeadlines(deal: Deal, metrics: Metric[], deckId: string): Flag[] {
  const deck = deckDoc(deal);
  if (!deck) return [];
  const out: Flag[] = [];
  for (const room of metrics) {
    if (!/headline/i.test(room.citation.sheet ?? "")) continue;
    const rounded = room.raw.includes("::") ? room.raw.split("::").slice(1).join("::").trim() : room.raw;
    const label = room.citation.label ?? room.name;
    let page = pageFor(deal, rounded) ?? pageFor(deal, label);
    let quote = rounded;
    for (const [num, text] of Object.entries(deck.pageTexts)) {
      const n = firstNumber(text);
      if (n == null) continue;
      const about = new RegExp(label.split(/\s+/).slice(0, 3).join("|"), "i").test(text);
      const hasRounded = rounded.length > 2 && text.toLowerCase().includes(rounded.toLowerCase().slice(0, 18));
      if (!about && !hasRounded) continue;
      const floor = /[+>]|–|-/.test(rounded);
      if (floor && n === firstNumber(rounded)) continue;
      if (relDiff(n, room.value) < 0.03) continue;
      if (Math.abs(n - room.value) < 1 && room.unit !== "usd") continue;
      page = Number(num);
      const hit = text.match(/(\d[\d,.]*(?:\+|x|%|bn|m|k)?)/i);
      quote = hit?.[0] ?? rounded;
      out.push({
        id: `flag-${room.name}`,
        docId: deckId,
        page,
        type: "highlight",
        severity: "contradiction",
        metric: room.name,
        quote,
        comment: `Deck shows ${quote}; the model calculates ${room.value}${rounded ? ` (slide form ${rounded})` : ""}.`,
        sourceCitation: citationLabel(room.citation),
        sourceFile: room.citation.filename,
        sourceSheet: room.citation.sheet,
        deckValue: quote,
        roomValue: rounded || String(room.value),
      });
      break;
    }
  }
  return out;
}

